#[derive(Clone, Copy)]
pub enum Act { SetTrue, Set, Append, Count, Help, Version }

pub struct ArgSpec { pub id: &'static str, pub long: &'static str, pub short: Option<char>, pub val: Option<&'static str>, pub action: Act, pub pv: &'static [&'static str], pub help: &'static str, pub lhelp: &'static str, pub hidden: bool, pub overrides: bool }

pub const ARGS: &[ArgSpec] = &[ ...table... ];

pub fn build_command(name: &str) -> Command {
    let mut cmd = Command::new(name)...
    for spec in ARGS {
        let mut arg = Arg::new(spec.id);
        if let Some(s) = spec.short { arg = arg.short(s); }
        arg = arg.long(spec.long);
        if let Some(v) = spec.val { arg = arg.value_name(v); }
        arg = arg.action(match spec.action { ... });
        if !spec.pv.is_empty() { arg = arg.value_parser(spec.pv); }
        arg = arg.help(spec.help);
        if spec.lhelp != spec.help { arg = arg.long_help(spec.lhelp); }
        if spec.hidden { arg = arg.hide(true); }
        if spec.overrides { arg = arg.overrides_with(main_id_for(spec)); }
        cmd = cmd.arg(arg);
    }
    // positionals
    cmd.arg(...).arg(...)
}
