//! A header map with the same semantics as the one used by the reference
//! implementation's HTTP library: insertion order is preserved, inserting an
//! existing name replaces its values in place, appending adds an extra value and
//! removing moves the last entry into the freed slot.

#[derive(Debug, Clone, Default)]
pub struct Headers {
    entries: Vec<(String, Vec<String>)>,
}

impl Headers {
    pub fn new() -> Self {
        Headers { entries: vec![] }
    }

    fn entry_index(&self, name: &str) -> Option<usize> {
        let lower = name.to_ascii_lowercase();
        self.entries.iter().position(|(n, _)| n.to_ascii_lowercase() == lower)
    }

    /// Insert: replaces the values of an existing entry (keeping its position)
    /// or appends a new entry.
    pub fn insert(&mut self, name: &str, value: &str) {
        if let Some(idx) = self.entry_index(name) {
            self.entries[idx].1 = vec![value.to_string()];
        } else {
            self.entries.push((name.to_string(), vec![value.to_string()]));
        }
    }

    /// Append: adds an extra value to an existing entry or creates a new one.
    pub fn append(&mut self, name: &str, value: &str) {
        if let Some(idx) = self.entry_index(name) {
            self.entries[idx].1.push(value.to_string());
        } else {
            self.entries.push((name.to_string(), vec![value.to_string()]));
        }
    }

    /// Remove: the last entry is moved into the freed slot.
    pub fn remove(&mut self, name: &str) -> bool {
        if let Some(idx) = self.entry_index(name) {
            let last = self.entries.len() - 1;
            self.entries.swap(idx, last);
            self.entries.pop();
            true
        } else {
            false
        }
    }

    pub fn contains(&self, name: &str) -> bool {
        self.entry_index(name).is_some()
    }

    pub fn get(&self, name: &str) -> Option<&str> {
        self.entry_index(name).map(|i| self.entries[i].1[0].as_str())
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn iter(&self) -> impl Iterator<Item = (&str, &str)> {
        self.entries.iter().flat_map(|(n, vs)| vs.iter().map(move |v| (n.as_str(), v.as_str())))
    }

    pub fn names(&self) -> impl Iterator<Item = &str> {
        self.entries.iter().map(|(n, _)| n.as_str())
    }

    /// Sort the entries by name (used when formatting is enabled).
    pub fn sort(&mut self) {
        self.entries.sort_by(|a, b| a.0.to_ascii_lowercase().cmp(&b.0.to_ascii_lowercase()));
    }
}
RSEOF
echo ok"}

