//! URL handling helpers: scheme defaults, the ":host" shorthand and query
//! string merging.

use percent_encoding::{utf8_percent_encode, NON_ALPHANUMERIC};
use url::Url;

pub fn default_scheme(cli_default: Option<&str>, https_flag: bool, bin_name: &str) -> String {
    if let Some(s) = cli_default {
        return s.to_string();
    }
    if matches!(bin_name, "xhs" | "https" | "xhttps") {
        return "https".to_string();
    }
    if https_flag {
        return "https".to_string();
    }
    "http".to_string()
}

/// Expand the URL following xh's shorthand rules:
///
/// * `:8000`      -> scheme://localhost:8000
/// * `:/path`     -> scheme://localhost/path
/// * `://host`    -> scheme://host
/// * `//host`     -> scheme://host
pub fn expand_url(url: &str, scheme: &str) -> String {
    let expanded = if let Some(rest) = url.strip_prefix(':') {
        format!("{}://localhost{}", scheme, rest)
    } else if let Some(rest) = url.strip_prefix("://") {
        format!("{}://{}", scheme, rest)
    } else if let Some(rest) = url.strip_prefix("//") {
        format!("{}://{}", scheme, rest)
    } else if !url.contains("://") {
        format!("{}://{}", scheme, url)
    } else {
        url.to_string()
    };
    expanded
}

pub fn parse(url: &str) -> Result<Url, String> {
    Url::parse(url).map_err(|e| e.to_string())
}

/// Encode a query string item the way `form_urlencoded` does.
pub fn encode_query_component(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => out.push(b as char),
            b' ' => out.push('+'),
            _ => {
                for c in utf8_percent_encode(std::str::from_utf8(&[b]).unwrap_or("?"), NON_ALPHANUMERIC) {
                    out.push(c);
                }
            }
        }
    }
    out
}

/// Append query string items to a URL.
pub fn append_query(url: &mut Url, items: &[(String, String)]) {
    if items.is_empty() {
        return;
    }
    let mut query = url.query().map(|q| q.to_string()).unwrap_or_default();
    for (k, v) in items {
        if !query.is_empty() {
            query.push('&');
        }
        query.push_str(&encode_query_component(k));
        if !v.is_empty() {
            query.push('=');
            query.push_str(&encode_query_component(v));
        }
    }
    url.set_query(Some(&query));
}

/// Return the host header value for a URL, mirroring how the HTTP library
/// derives it (userinfo stripped, default port omitted).
pub fn host_header(url: &Url) -> String {
    let host = url.host_str().unwrap_or("");
    match url.port_or_known_default() {
        Some(p) => {
            let is_default = matches!(
                (url.scheme(), p),
                ("http", 80) | ("https", 443) | ("ws", 80) | ("wss", 443) | ("ftp", 21)
            );
            if is_default {
                host.to_string()
            } else {
                format!("{}:{}", host, p)
            }
        }
        None => host.to_string(),
    }
}

pub fn is_ipv6_host(host: &str) -> bool {
    host.starts_with('[')
}
RSEOF
echo ok"}

