}

/// Encode a query string item the way `form_urlencoded` does.
pub fn encode_query_component(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => out.push(b as char),
            b' ' => out.push('+'),
            _ => {
                for c in utf8_percent_encode(std::str::from_utf8(&[b]).unwrap_or("?"), NON_ALPHANUMERIC) {
