    SEPARATORS.contains(c) || c == '\\'
}

/// Unescape `\X` for X in the set of syntax characters, leaving everything
/// else untouched.
pub fn unescape(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some(n) if is_special(n) => out.push(n),
                Some(n) => {
                    out.push('\\');
                    out.push(n);
                }
                None => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Scan `item` for the first unescaped separator character, returning
/// (character, byte index). Escaped characters are skipped over.
fn find_separator(item: &str) -> Option<(char, usize, usize)> {
    let bytes = item.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'\\' {
            // Skip the next character (or just this one if it is the last)
            i += 2;
            continue;
        }
        if i == 0 && bytes[i] == b'@' {
            return Some(('@', i, 1));
        }
        let c = bytes[i] as char;
        if c == '=' {
            if i + 1 < bytes.len() && bytes[i + 1] == b'=' {
                return Some(('q', i, 2)); // query string "==" handled below
            }
            return Some(('=', i, 1));
        }
        if c == ':' {
            if i + 1 < bytes.len() && bytes[i + 1] == b'=' {
                return Some(('j', i, 2)); // ":="
            }
            return Some((':', i, 1));
        }
        if c == ';' && i + 1 == bytes.len() {
            return Some((';', i, 1));
        }
        i += 1;
    }
    None
}

pub fn parse(item: &str) -> Result<RequestItem, ()> {
    let (kind, idx, len) = match find_separator(item) {
        Some(v) => v,
        None => return Err(()),
    };
    let key = &item[..idx];
    let value = &item[idx + len..];
    match kind {
        'q' => Ok(RequestItem::QueryString(unescape(key), unescape(value))),
        '=' => {
            if value.starts_with('@') {
                Ok(RequestItem::DataField(unescape(key), unescape(&value[1..]), false))
            } else {
                Ok(RequestItem::DataField(unescape(key), unescape(value), false))
            }
        }
        'j' => {
            if value.starts_with('@') {
                Ok(RequestItem::DataField(unescape(key), unescape(&value[1..]), true))
            } else {
                Ok(RequestItem::DataField(unescape(key), unescape(value), true))
            }
        }
        ':' => {
            if value.is_empty() {
                Ok(RequestItem::Header(unescape(key), None))
            } else if value.starts_with('@') {
                let path = unescape(&value[1..]);
                let content = std::fs::read_to_string(&path)
                    .map_err(|e| { eprintln!("{}: error: {}", crate::PROGRAM, crate::io_error(&e)); std::process::exit(1) })
                    .unwrap_or_default();
                Ok(RequestItem::Header(unescape(key), Some(content)))
            } else {
                Ok(RequestItem::Header(unescape(key), Some(unescape(value))))
            }
        }
        ';' => Ok(RequestItem::Header(unescape(key), Some(String::new()))),
        '@' => {
            if idx == 0 && !key.is_empty() {
                return Err(());
            }
            let path = unescape(value);
            Ok(RequestItem::FileBody(path))
        }
        _ => {
            // key@filename ;type=mime;filename=name
            let (filename, extra) = parse_file_value(value);
            Ok(RequestItem::FileField {
                key: unescape(key),
                filename: unescape(&filename),
                mime: extra.0,
                name: extra.1,
            })
        }
    }
}

/// Split `filename;type=mime;filename=name`.
fn parse_file_value(value: &str) -> (String, (Option<String>, Option<String>)) {
    let mut parts = value.split(';');
    let filename = parts.next().unwrap_or("").to_string();
    let mut mime = None;
    let mut name = None;
    for part in parts {
        if let Some(t) = part.strip_prefix("type=") {
            mime = Some(t.to_string());
        } else if let Some(n) = part.strip_prefix("filename=") {
            name = Some(n.to_string());
        }
    }
    (filename, (mime, name))
}
