        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

pub fn parse_path(key: &str) -> Result<Vec<PathPart>, PathError> {
    let chars: Vec<char> = key.chars().collect();
    let len = chars.len();
    let mut pos = 0usize;
    let mut parts: Vec<PathPart> = vec![];

    if pos >= len {
        return Err(PathError { msg: "expected text or '['".into(), pos });
    }
    if chars[pos] == '[' {
        pos += 1;
        if pos >= len {
            return Err(PathError { msg: "expected number or ']'".into(), pos });
        }
        if chars[pos] == ']' {
            parts.push(PathPart::IndexAppend);
            pos += 1;
