            let start = pos;
            while pos < len && chars[pos].is_ascii_digit() {
                pos += 1;
            }
            let n: usize = chars[start..pos].iter().collect::<String>().parse().unwrap_or(0);
            if pos >= len || chars[pos] != ']' {
                return Err(PathError { msg: "expected number or ']'".into(), pos });
            }
            parts.push(PathPart::Index(n));
            pos += 1;
        } else {
            return Err(PathError { msg: "expected number or ']'".into(), pos });
        }
    } else {
        let start = pos;
        while pos < len && chars[pos] != '[' && chars[pos] != ']' {
            pos += 1;
        }
        if pos == start {
            return Err(PathError { msg: "expected text or '['".into(), pos });
        }
        parts.push(PathPart::Key(chars[start..pos].iter().collect()));
    }

    loop {
        if pos >= len {
            break;
        }
        if chars[pos] != '[' {
            return Err(PathError { msg: "expected '['".into(), pos });
        }
        pos += 1;
        if pos >= len {
            return Err(PathError { msg: "expected text, number or ']'".into(), pos });
        }
        if chars[pos] == ']' {
            parts.push(PathPart::IndexAppend);
            pos += 1;
            continue;
        }
        if chars[pos].is_ascii_digit() {
            let start = pos;
            while pos < len && chars[pos].is_ascii_digit() {
                pos += 1;
            }
            let n: usize = chars[start..pos].iter().collect::<String>().parse().unwrap_or(0);
            if pos >= len {
                return Err(PathError { msg: "expected ']'".into(), pos });
            }
            if chars[pos] == ']' {
                parts.push(PathPart::Index(n));
                pos += 1;
                continue;
            }
        }
        // Text component
        let start = pos;
        while pos < len && chars[pos] != '[' && chars[pos] != ']' {
            pos += 1;
        }
        if pos >= len {
            return Err(PathError { msg: "expected ']'".into(), pos });
        }
        if pos == start {
            return Err(PathError { msg: "expected text, number or ']'".into(), pos });
        }
        parts.push(PathPart::Key(chars[start..pos].iter().collect()));
        pos += 1;
    }
    Ok(parts)
}

fn build(parts: &[PathPart], idx: usize, value: Value) -> Value {
    match parts.get(idx) {
        None => value,
        Some(PathPart::Key(k)) => {
            let mut obj = Map::new();
            obj.insert(k.clone(), build(parts, idx + 1, value));
            Value::Object(obj)
        }
        Some(PathPart::Index(n)) => {
            let mut arr = vec![];
            for i in 0..*n {
                arr.push(Value::Null);
            }
            arr.push(build(parts, idx + 1, value));
            Value::Array(arr)
        }
        Some(PathPart::IndexAppend) => {
            Value::Array(vec![build(parts, idx + 1, value)])
        }
    }
