            pos += 1;
        }
        if pos < chars.len() {
            pos += 1;
        }
    } else {
        while pos < chars.len() && chars[pos] != '[' && chars[pos] != ']' {
            pos += 1;
        }
    }
    seg += 1;
    while seg < segment && pos < chars.len() {
        pos += 1; // skip '['
        while pos < chars.len() && chars[pos] != ']' {
            pos += 1;
        }
        if pos < chars.len() {
            pos += 1;
        }
        seg += 1;
    }
    pos
