        parts.push(PathPart::Key(chars[start..pos].iter().collect()));
        pos += 1;
    }
    Ok(parts)
}

fn build(parts: &[PathPart], idx: usize, value: Value) -> Value {
    match parts.get(idx) {
        None => value,
        Some(PathPart::Key(k)) => {
            let mut obj = Map::new();
            obj.insert(k.clone(), build(parts, idx + 1, value));
            Value::Object(obj)
        }
        Some(PathPart::Index(n)) => {
            let mut arr = vec![];
            for i in 0..*n {
                arr.push(Value::Null);
            }
            arr.push(build(parts, idx + 1, value));
            Value::Array(arr)
        }
        Some(PathPart::IndexAppend) => {
            Value::Array(vec![build(parts, idx + 1, value)])
        }
    }
}

fn merge_key(existing: &mut Value, key: &str, rest: &[PathPart], idx: usize, value: Value) -> Result<(), (usize, usize, &'static str, &'static str)> {
    // returns Err((segment_index, pos_in_key, existing_type, required))
    match existing {
        Value::Object(_) => {
            let obj = existing.as_object_mut().unwrap();
            let cur = obj.get_mut(key);
            match cur {
                Some(v) => merge_into(v, rest, idx, value),
                None => {
                    obj.insert(key.to_string(), build(rest, idx, value));
                    Ok(())
                }
            }
        }
        other => Err((idx, 0, crate::to_json::type_name(other), "object")),
    }
}

fn merge_into(existing: &mut Value, rest: &[PathPart], idx: usize, value: Value) -> Result<(), (usize, usize, &'static str, &'static str)> {
    if idx >= rest.len() {
        *existing = value;
        return Ok(());
    }
    match &rest[idx] {
        PathPart::Key(k) => match existing {
            Value::Object(_) => {
                let obj = existing.as_object_mut().unwrap();
                if let Some(v) = obj.get_mut(k) {
                    merge_into(v, rest, idx + 1, value)
                } else {
                    obj.insert(k.clone(), build(rest, idx + 1, value));
                    Ok(())
                }
            }
            other => Err((idx, 0, crate::to_json::type_name(other), "object")),
        },
        PathPart::Index(n) => match existing {
            Value::Array(arr) => {
                if *n < arr.len() {
                    merge_into(&mut arr[*n], rest, idx + 1, value)
                } else {
                    for _ in arr.len()..*n {
                        arr.push(Value::Null);
                    }
                    arr.push(build(rest, idx + 1, value));
                    Ok(())
                }
            }
            other => Err((idx, 0, crate::to_json::type_name(other), "array")),
        },
        PathPart::IndexAppend => match existing {
            Value::Array(arr) => {
                arr.push(build(rest, idx + 1, value));
                Ok(())
            }
            other => Err((idx, 0, crate::to_json::type_name(other), "array")),
        },
    }
}

/// Insert a value at the given path into the root JSON structure.
pub fn set(root: &mut Value, parts: &[PathPart], value: Value) -> Result<(), SetError> {
    if parts.is_empty() {
        *root = value;
        return Ok(());
    }
    match merge_into(root, parts, 0, value) {
        Ok(()) => Ok(()),
        Err((seg_idx, _pos, actual, required)) => Err(SetError {
            segment: seg_idx,
            actual: actual.to_string(),
            required: required.to_string(),
        }),
    }
}

pub struct SetError {
    /// Index of the path part that failed
    pub segment: usize,
    pub actual: String,
    pub required: String,
}

/// Render the path prefix up to (excluding) `segment` the way the reference
/// implementation does.
pub fn render_prefix(parts: &[PathPart], segment: usize) -> String {
    let mut s = String::new();
    for part in &parts[..segment.min(parts.len())] {
        match part {
            PathPart::Key(k) => s.push_str(k),
            PathPart::Index(n) => {
                s.push('[');
                s.push_str(&n.to_string());
                s.push(']');
            }
            PathPart::IndexAppend => s.push_str("[]"),
        }
    }
    s
}

/// The character offset (within the original key) of the '[' introducing
/// `segment`.
pub fn segment_offset(key: &str, segment: usize) -> usize {
    let chars: Vec<char> = key.chars().collect();
    let mut pos = 0usize;
    let mut seg = 0usize;
    if seg == segment {
        return 0;
    }
    // Skip the first component (text or index)
    if chars[pos] == '[' {
        pos += 1;
        while pos < chars.len() && chars[pos] != ']' {
            pos += 1;
        }
        if pos < chars.len() {
            pos += 1;
        }
    } else {
        while pos < chars.len() && chars[pos] != '[' && chars[pos] != ']' {
            pos += 1;
        }
    }
    seg += 1;
    while seg < segment && pos < chars.len() {
        pos += 1; // skip '['
        while pos < chars.len() && chars[pos] != ']' {
            pos += 1;
        }
        if pos < chars.len() {
            pos += 1;
        }
        seg += 1;
    }
    pos
}
