//! Building the request body from request items, stdin and files.

use serde_json::Value;

pub struct Part {
    pub name: String,
    pub filename: Option<String>,
    pub mime: Option<String>,
    pub content: Vec<u8>,
}

#[derive(Debug)]
pub enum Body {
    /// JSON built from data items
    Json(Value),
    /// Raw JSON data (from stdin or --raw)
    JsonRaw(Vec<u8>),
    Form(Vec<(String, String)>),
    Multipart(Vec<Part>, String),
    File(Vec<u8>, String),
    None,
}

impl Body {
    pub fn content_type(&self) -> Option<String> {
        match self {
            Body::Json(_) => Some("application/json".to_string()),
            Body::JsonRaw(_) => Some("application/json".to_string()),
            Body::Form(_) => Some("application/x-www-form-urlencoded".to_string()),
            Body::Multipart(_, boundary) => Some(format!("multipart/form-data; boundary={}", boundary)),
            Body::File(_, ct) => Some(ct.clone()),
            Body::None => None,
        }
    }

    pub fn to_bytes(&self) -> Option<Vec<u8>> {
        match self {
            Body::Json(v) => {
                if v.as_object().map(|m| m.is_empty()).unwrap_or(false) {
                    None
                } else {
                    Some(crate::json::to_compact_string(v).into_bytes())
                }
            }
            Body::JsonRaw(b) => Some(b.clone()),
            Body::Form(pairs) => {
                let mut out = String::new();
                for (i, (k, v)) in pairs.iter().enumerate() {
                    if i > 0 {
                        out.push('&');
                    }
                    out.push_str(&crate::url::encode_query_component(k));
                    out.push('=');
                    out.push_str(&crate::url::encode_query_component(v));
                }
                Some(out.into_bytes())
            }
            Body::Multipart(parts, boundary) => {
                let mut out: Vec<u8> = vec![];
                for part in parts {
                    out.extend_from_slice(format!("--{}\r\n", boundary).as_bytes());
                    let mut cd = format!("Content-Disposition: form-data; name=\"{}\"", part.name);
                    if let Some(f) = &part.filename {
                        cd.push_str(&format!("; filename=\"{}\"", f));
                    }
                    out.extend_from_slice(cd.as_bytes());
                    out.extend_from_slice(b"\r\n");
                    if let Some(m) = &part.mime {
                        out.extend_from_slice(format!("Content-Type: {}\r\n", m).as_bytes());
                    }
                    out.extend_from_slice(b"\r\n");
                    out.extend_from_slice(&part.content);
                    out.extend_from_slice(b"\r\n");
                }
                out.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
                Some(out)
            }
            Body::File(b, _) => Some(b.clone()),
            Body::None => None,
        }
    }
}

pub fn new_boundary() -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let mut hex = String::new();
    for _ in 0..32 {
        hex.push_str(&format!("{:02x}", rng.gen::<u8>()));
    }
    let groups: Vec<String> = hex.as_bytes().chunks(16).map(|c| String::from_utf_lossy(c).to_string()).collect();
    groups.join("-")
}
