//! A minimal syntax highlighter reproducing the output of the reference
//! implementation for the JSON syntax that ships with it, plus simple
//! highlighters for HTML, XML, CSS and JavaScript.

#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Style {
    pub fg: Option<u8>,
    pub underline: bool,
    pub bold: bool,
    pub italic: bool,
}

impl Style {
    pub fn plain() -> Style {
        Style { fg: None, underline: false, bold: false, italic: false }
    }
    pub fn fg(c: u8) -> Style {
        Style { fg: Some(c), ..Style::plain() }
    }
    pub fn to_ansi(&self) -> String {
        let mut s = String::from("\x1b[0m");
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if self.italic {
            s.push_str("\x1b[3m");
        }
        if self.underline {
            s.push_str("\x1b[4m");
        }
        if let Some(c) = self.fg {
            s.push_str(&ansi_fg(c));
        }
        s
    }
}

pub fn ansi_fg(c: u8) -> String {
    if c < 8 {
        format!("\x1b[{}m", 30 + c)
    } else if c == 8 {
        "\x1b[90m".to_string()
    } else {
        format!("\x1b[38;5;{}m", c)
    }
}

/// Scope selector -> style for a theme.
pub struct Theme {
    pub name: &'static str,
    /// (scope prefix, style) pairs, most specific first
    pub rules: Vec<(&'static str, Style)>,
    pub default: Style,
}

/// Resolve a scope string such as `constant.numeric.jsonkv` to a style.
pub fn theme_style(theme: &Theme, scopes: &[&str]) -> Style {
    for (prefix, style) in &theme.rules {
        for scope in scopes {
            if scope_starts_with(scope, prefix) {
                return *style;
            }
        }
    }
    theme.default
}

/// syntect-style scope matching: `constant.numeric` matches
/// `constant.numeric.jsonkv`.
fn scope_starts_with(scope: &str, prefix: &str) -> bool {
    if prefix.is_empty() {
        return true;
    }
    let mut rest = scope;
    loop {
        if rest == prefix {
            return true;
        }
        match rest.rfind('.') {
            Some(i) => rest = &rest[..i],
            None => break,
        }
    }
    false
}

