pub const RESET: &str = "\x1b[0m";

/// Render highlighted regions as ANSI escape codes.
pub fn to_ansi(regions: &[(Style, &str)]) -> String {
    let mut out = String::new();
    for (style, text) in regions {
        out.push_str(&style.to_ansi());
        out.push_str(text);
    }
    out.push_str(RESET);
    out
}

// ---------------------------------------------------------------- JSON -----

/// Tokenize according to the bundled "JSON Key-Value" syntax.
pub fn highlight_json(text: &str, theme: &Theme) -> String {
    let mut out = String::new();
    let mut chars: Vec<(usize, char)> = text.char_indices().collect();
    let mut i = 0usize;
    let mut in_block_comment = false;
    let n = chars.len();
    while i < n {
        let (byte, c) = chars[i];
        if in_block_comment {
            // find */
            let rest: String = chars[i..].iter().map(|x| x.1).collect();
            match rest.find("*/") {
                Some(idx) => {
                    let scopes = ["comment.block.jsonkv"];
                    let st = theme_style(theme, &scopes);
                    let seg: String = rest[..idx + 2].chars().collect();
                    out.push_str(&st.to_ansi());
                    out.push_str(&seg);
                    i += seg.chars().count();
                    in_block_comment = false;
                    continue;
                }
                None => {
                    let scopes = ["comment.block.jsonkv"];
                    let st = theme_style(theme, &scopes);
                    out.push_str(&st.to_ansi());
                    out.push_str(&rest);
                    return out;
                }
            }
        }
        // line comment
        if c == '/' && chars.get(i + 1).map(|x| x.1) == Some('/') {
            let start = byte;
            let mut j = i;
            while j < n && chars[j].1 != '\n' {
                j += 1;
            }
            let end = if j < n { chars[j].0 } else { text.len() };
            let st = theme_style(theme, &["comment.single.line.jsonkv"]);
            out.push_str(&st.to_ansi());
            out.push_str(&text[start..end]);
            i = j;
            continue;
        }
        if c == '/' && chars.get(i + 1).map(|x| x.1) == Some('*') {
            in_block_comment = true;
            i += 1;
            continue;
        }
        // key name: (")(?i)([^\\"]+)(") followed by optional ws and ':'
        if c == '"' {
            // try key
            let rest: String = chars[i..].iter().map(|x| x.1).collect();
            let mut k = 1usize; // after opening quote
            let mut name_len = 0usize;
            while k < rest.len() && !rest[k..].starts_with('\\') && !rest[k..].starts_with('"') {
                name_len += rest[k..].chars().next().unwrap().len_utfk();
                k += rest[k..].chars().next().unwrap().len_utfk();
            }
            let _ = name_len;
            if k < rest.len() && rest[k..].starts_with('"') {
                let after = &rest[k + 1..];
                let ws = after.chars().take_while(|ch| ch.is_whitespace() && *ch != '\n').count();
