        }
        s
    }
}

pub fn ansi_fg(c: u8) -> String {
    if c < 8 {
        format!("\x1b[{}m", 30 + c)
    } else if c == 8 {
        "\x1b[90m".to_string()
    } else {
        format!("\x1b[38;5;{}m", c)
    }
}

/// Scope selector -> style for a theme.
pub struct Theme {
    pub name: &'static str,
