            while k < rest.len() && !rest[k..].starts_with('\\') && !rest[k..].starts_with('"') {
                name_len += rest[k..].chars().next().unwrap().len_utfk();
                k += rest[k..].chars().next().unwrap().len_utfk();
            }
            let _ = name_len;
            if k < rest.len() && rest[k..].starts_with('"') {
                let after = &rest[k + 1..];
                let ws = after.chars().take_while(|ch| ch.is_whitespace() && *ch != '\n').count();
                if after[after.chars().take(ws).map(|c| c.len_utfk()).sum::<usize>()..].starts_with(':') {
                    let scopes_start = ["keyword.other.name.jsonkv.start"];
                    let scopes_name = ["keyword.other.name.jsonkv"];
                    let scopes_end = ["keyword.other.name.jsonkv.end"];
                    let st_start = theme_style(theme, &scopes_start);
                    let st_name = theme_style(theme, &scopes_name);
                    let st_end = theme_style(theme, &scopes_end);
                    out.push_str(&st_start.to_ansi());
                    out.push('"');
                    let name: String = rest[1..k].chars().collect();
                    out.push_str(&st_name.to_ansi());
                    out.push_str(&name);
                    out.push_str(&st_end.to_ansi());
                    out.push('"');
                    i += 1 + name.chars().count() + 1;
                    continue;
                }
            }
            // string value
            let st = theme_style(theme, &["string.quoted.jsonkv"]);
            out.push_str(&st.to_ansi());
            out.push('"');
            i += 1;
            // consume until closing quote, colouring escapes
            while i < n {
                let (b2, c2) = chars[i];
                if c2 == '\\' && i + 1 < n {
                    let next = chars[i + 1].1;
                    if "tnr\"".contains(next) {
                        // escape token
                        let st_esc = theme_style(theme, &["constant.character.escape.jsonkv"]);
                        out.push_str(&st_esc.to_ansi());
                        out.push('\\');
                        out.push(next);
                        i += 2;
                        continue;
                    }
                    out.push('\\');
                    i += 1;
                    continue;
                }
                if c2 == '"' {
                    out.push('"');
                    i += 1;
                    break;
                }
                out.push(c2);
                i += 1;
            }
            continue;
        }
        // number
        if c.is_ascii_digit() {
            let start = byte;
            let mut j = i;
            let mut saw_dot = false;
            while j < n {
                let cj = chars[j].1;
                if cj.is_ascii_digit() {
                    j += 1;
                } else if cj == '.' && !saw_dot {
                    saw_dot = true;
                    j += 1;
                } else {
                    break;
                }
            }
            let end = if j < n { chars[j].0 } else { text.len() };
            let st = theme_style(theme, &["constant.numeric.jsonkv"]);
            out.push_str(&st.to_ansi());
            out.push_str(&text[start..end]);
            i = j;
            continue;
        }
        if text[byte..].starts_with("true") || text[byte..].starts_with("false") {
            let word = if text[byte..].starts_with("true") { "true" } else { "false" };
            let st = theme_style(theme, &["constant.language.boolean.jsonkv"]);
            out.push_str(&st.to_ansi());
            out.push_str(word);
            i += word.chars().count();
            continue;
        }
        if text[byte..].starts_with("null") {
            let st = theme_style(theme, &["constant.language.null.jsonkv"]);
            out.push_str(&st.to_ansi());
            out.push_str("null");
            i += 4;
            continue;
        }
        out.push(c);
        i += 1;
    }
    out
}
