mod args;
mod cli;
mod body;
mod generate;
mod headers;
mod highlight;
mod json;
mod mime;
mod nushell;
mod print;
mod request;
mod request_items;
mod to_curl;
mod to_json;
mod url;
mod utils;

use clap::ArgMatches;
use std::io::Write;

pub const PROGRAM: &str = "xh";

/// The program name used in error messages (basename of argv[0]).
pub fn program_name() -> String {
    std::env::args()
        .next()
        .map(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or(a)
        })
        .unwrap_or_else(|| PROGRAM.to_string())
}

pub fn io_error(e: &std::io::Error) -> String {
    e.to_string()
}

pub fn fish_hook(bin: &str) -> String {
    format!(
        "# Complete paths after @ in options:\nfunction __{}_complete_data\n    string match -qr '^(?<prefix>.*@)(?<path>.*)' -- (commandline -ct)\n    printf '%s\\n' -- $prefix(__fish_complete_path $path)\nend\ncomplete -c {} -n 'string match -qr \"@\" -- (commandline -ct)' -kxa \"(__{}_complete_data)\"\n\n",
        bin, bin, bin
    )
}

pub fn fish_hook_end(_bin: &str) -> &'static str {
    ""
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let bin_name = program_name();
    let mut cmd = args::build_command(&bin_name);
    let matches: ArgMatches = match cmd.clone().try_get_matches_from(&argv) {
        Ok(m) => m,
        Err(e) => e.exit(),
    };

    // `xh help` prints the long help
    if matches.get_one::<String>("raw_method_or_url").map(|s| s.as_str()) == Some("help") {
        let mut cmd2 = args::build_command(&bin_name);
        cmd2.build();
        let help = cmd2.render_long_help();
        print!("{}", help);
        std::process::exit(0);
    }

    let cli = cli::cli_from_matches(&matches);

    if let Some(kind) = &cli.generate {
        generate::generate(kind, &bin_name);
        return;
    }

    request::run(&cli, &bin_name, &cmd);
}
RSEOF
