{"command": "cd /workspace && cat > src/request.rs <<'RSEOF'
//! Building and printing HTTP requests from the command line arguments.

use crate::args::Act;
use clap::{Error, ErrorKind};
use std::io::Write;
use std::io::Read;
use url::Url;

use crate::body::{new_boundary, Body, Part};
use crate::headers::Headers;
use crate::request_items::{parse, RequestItem};
use crate::to_json::{parse_path, PathError, PathPart, SetError};

pub struct RequestData {
    pub method: String,
    pub url: Url,
    pub headers: Headers,
    pub body: Body,
    pub body_is_json_map: bool,
}

fn user_error(msg: String) -> ! {
    eprintln!("{}: error: {}", crate::PROGRAM, msg);
    std::process::exit(1)
}

fn clap_error(msg: String, kind: ErrorKind) -> ! {
    let mut cmd = crate::args::build_command(crate::PROGRAM);
    cmd.build();
    cmd.error(kind, msg).exit()
}

fn cmd_error(cmd: &clap::Command, msg: String, kind: ErrorKind) -> ! {
    let mut c = cmd.clone();
    c.build();
    c.error(kind, msg).exit()
}

/// Decide whether the request items imply JSON mode.
pub fn run(cli: &crate::cli::Cli, bin_name: &str, cmd: &clap::Command) {
    let mut cmd_mut = cmd.clone();
    cmd_mut.build();

    // Split the first positional into a method and a URL
    let first = cli.url.clone();
    let rest = &cli.request_items;
    let (method, url_str, items): (Option<String>, String, Vec<String>) = if crate::cli::is_http_method(&first) {
        if rest.is_empty() {
            cmd_error(&cmd_mut, "Missing <URL>".to_string(), ErrorKind::MissingSubcommand);
        }
        (Some(first.to_uppercase()), rest[0].clone(), rest[1..].to_vec())
    } else {
        (None, first.clone(), rest.clone())
    };

    // Parse the request items
    let mut query_items: Vec<(String, String)> = vec![];
    let mut data_items: Vec<(String, serde_json::Value)> = vec![];
    let mut header_items: Vec<(String, Option<String>)> = vec![];
    let mut file_fields: Vec<(String, String, Option<String>, Option<String>)> = vec![];
    let mut file_body: Option<String> = None;
    let mut has_raw_value_data = false;

    for item in &items {
        match parse(item) {
            Ok(RequestItem::QueryString(k, v)) => {
                let v = if v.starts_with('@') { read_file(&v[1..]) } else { v };
                query_items.push((k, v));
            }
            Ok(RequestItem::DataField(k, v, literal)) => {
                if literal {
                    if v.starts_with('@') {
                        let content = read_file(&v[1..]);
                        match serde_json::from_str::<serde_json::Value>(&content) {
                            Ok(val) => data_items.push((k, val)),
                            Err(e) => {
                                let mut c = cmd_mut.clone();
                                c.build();
                                c.error(ErrorKind::InvalidValue, format!("Invalid value for '[REQUEST_ITEM]...': {:?} {}", item, e)).exit();
                            }
                        }
                    } else {
                        match serde_json::from_str::<serde_json::Value>(&v) {
                            Ok(val) => data_items.push((k, val)),
                            Err(e) => {
                                let mut c = cmd_mut.clone();
                                c.build();
                                c.error(ErrorKind::InvalidValue, format!("Invalid value for '[REQUEST_ITEM]...': {:?} {}", item, e)).exit();
                            }
                        }
                    }
                } else {
                    let v = if v.starts_with('@') { read_file(&v[1..]) } else { v };
                    data_items.push((k, serde_json::Value::String(v)));
                }
                has_raw_value_data = true;
            }
            Ok(RequestItem::FileField { key, filename, mime, name }) => {
                file_fields.push((key, filename, mime, name));
            }
            Ok(RequestItem::FileBody(f)) => {
                file_body = Some(f);
            }
            Ok(RequestItem::Header(k, v)) => header_items.push((k, v)),
            Err(()) => {
                let mut c = cmd_mut.clone();
                c.build();
                c.error(ErrorKind::InvalidValue, format!("Invalid value for '[REQUEST_ITEM]...': {:?}", item)).exit();
            }
        }
    }

    // Expand and parse the URL
    let scheme = crate::url::default_scheme(cli.default_scheme.as_deref(), cli.https || cli_style_https(bin_name), bin_name);
    let expanded = crate::url::expand_url(&url_str, &scheme);
    let mut url = match crate::url::parse(&expanded) {
        Ok(u) => u,
        Err(e) => cmd_error(&cmd_mut, format!("Invalid <URL>: {}", e), ErrorKind::InvalidValue),
    };
    url.set_fragment(None);
    crate::url::append_query(&mut url, &query_items);

    // Request body from stdin
    let stdin_body: Option<Vec<u8>> = if cli.ignore_stdin || !stdin_is_redirected() {
        None
    } else {
        let mut buf = vec![];
        let _ = std::io::stdin().read_to_end(&mut buf);
        Some(buf)
    };

    // Determine the request type
    let mut request_type = if cli.multipart {
        "multipart"
    } else if cli.form {
        "form"
    } else if cli.json || !data_items.is_empty() || cli.raw.is_some() || stdin_body.is_some() || file_body.is_some() {
        "json"
    } else {
        "none"
    };
    if !file_fields.is_empty() && (cli.form || cli.multipart) {
        request_type = "multipart";
    }
    if !file_fields.is_empty() && request_type == "json" {
        user_error("Can't use file fields in JSON mode (perhaps you meant --form?)".to_string());
    }

    if let Some(raw) = &cli.raw {
        if !data_items.is_empty() {
            clap_error(
                if stdin_body.is_some() {
                    "Request body from stdin and --raw cannot be mixed. Pass --ignore-stdin to ignore standard input.".to_string()
                } else {
                    format!("Request body (from --raw) and request data ({} cannot be mixed.", "")
                },
                ErrorKind::ArgumentConflict,
            );
        }
    }
    let _ = has_raw_value_data;
    let _ = stdin_body;
    let _ = &method;
    let _ = &url;
    let _ = &file_fields;
    let _ = &file_body;
    let _ = &header_items;
    let _ = bin_name;
    let _ = request_type;
    let _ = &cli;
    std::process::exit(0);
}

fn cli_style_https(_bin: &str) -> bool {
    false
}

pub fn stdin_is_redirected() -> bool {
    !crate::utils::isatty_stdin()
}

fn read_file(path: &str) -> String {
    match std::fs::read(path) {
        Ok(b) => String::from_utf_lossy(&b).to_string(),
        Err(e) => {
            eprintln!("{}: error: No such file or directory (os error 2)", crate::PROGRAM);
            std::process::exit(1)
        }
    }
}
RSEOF
echo ok"}

