//! Building and printing HTTP requests from the command line arguments.

use clap::{ErrorKind};
use std::io::Write;
use std::io::Read;
use url::Url;

use crate::body::{new_boundary, Body, Part};
use crate::headers::Headers;
use crate::request_items::{parse, RequestItem};
use crate::to_json::{parse_path, PathPart};

pub struct Request {
    pub method: String,
    pub url: Url,
    pub headers: Headers,
    pub body: Body,
}

pub struct Items {
    pub query: Vec<(String, String)>,
    pub data: Vec<(String, serde_json::Value)>,
    pub headers: Vec<(String, Option<String>)>,
    pub files: Vec<(String, String, Option<String>, Option<String>)>,
    pub file_body: Option<String>,
}

pub fn user_error(msg: &str) -> ! {
    eprintln!("{}: error: {}", crate::PROGRAM, msg);
