fn cmd_error(cmd: &clap::Command, msg: String, kind: ErrorKind) -> ! {
    let mut c = cmd.clone();
    c.build();
    c.error(kind, msg).exit()
}

fn parse_json_value(s: &str, item: &str, cmd: &clap::Command) -> serde_json::Value {
    match serde_json::from_str::<serde_json::Value>(s) {
        Ok(v) => v,
        Err(e) => {
            let mut c = cmd.clone();
            c.build();
            c.error(ErrorKind::InvalidValue, format!("Invalid value for '[REQUEST_ITEM]...': {:?} {}", item, e)).exit();
        }
    }
}

/// Parse and validate all request items.
pub fn parse_items(items: &[String], cmd: &clap::Command) -> Items {
    let mut query = vec![];
    let mut data = vec![];
    let mut headers = vec![];
    let mut files = vec![];
    let mut file_body = None;

    for item in items {
        match parse(item) {
            Ok(RequestItem::QueryString(k, v)) => {
                let v = if let Some(path) = v.strip_prefix('@') { read_file(path, item, cmd) } else { v };
                query.push((k, v));
            }
            Ok(RequestItem::DataField(k, v, literal)) => {
                if let Some(path) = v.strip_prefix('@') {
                    let content = read_file(path, item, cmd);
                    if literal {
                        data.push((k, parse_json_value(&content, item, cmd)));
                    } else {
                        data.push((k, serde_json::Value::String(content)));
                    }
                } else if literal {
                    data.push((k, parse_json_value(&v, item, cmd)));
                } else {
                    data.push((k, serde_json::Value::String(v)));
                }
            }
            Ok(RequestItem::FileField { key, filename, mime, name }) => {
                if let Some(m) = &mime {
                    if !m.contains('/') {
                        let _ = user_error("builder error");
                    }
                }
                files.push((key, filename, mime, name));
            }
            Ok(RequestItem::FileBody(f)) => file_body = Some(f),
            Ok(RequestItem::Header(k, v)) => {
                let v = match v {
                    Some(v) => {
                        if let Some(path) = v.strip_prefix('@') {
                            Some(read_file(path, item, cmd))
                        } else {
                            Some(v)
                        }
                    }
                    None => None,
                };
                headers.push((k, v));
            }
            Err(()) => {
                let mut c = cmd.clone();
                c.build();
                c.error(ErrorKind::InvalidValue, format!("Invalid value for '[REQUEST_ITEM]...': {:?}", item)).exit();
