            std::process::exit(1)
        }
    }
}

/// Build the complete request from the CLI arguments.
pub fn build(cli: &crate::cli::Cli, bin_name: &str, cmd: &clap::Command) -> Request {
    let mut cmd_mut = cmd.clone();
