    if stdin_body.is_some() && (has_data || !items.files.is_empty()) {
        if request_type == Type::Multipart {
            user_error("Cannot build a multipart request body from stdin");
        }
        user_error("Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.");
    }

    // 7. Build the body.
    let body = build_body(cli, &items, stdin_body, request_type, &mut url);

    // 8. Build the headers.
    let headers = build_headers(cli, &body, request_type, &items, &url);

    // 9. Determine the method.
    let method = match method {
        Some(m) => m,
        None => {
            if body.to_bytes().is_some() || matches!(body, Body::Json(_)) {
                "POST".to_string()
            } else {
                "GET".to_string()
            }
        }
    };

    Request { method, url, headers, body }
}

#[derive(PartialEq, Clone, Copy)]
enum Type {
    Json,
    Form,
    Multipart,
    None,
}

fn build_body(
    cli: &crate::cli::Cli,
    items: &Items,
    stdin_body: Option<Vec<u8>>,
    request_type: Type,
    _url: &mut Url,
) -> Body {
    if let Some(raw) = &cli.raw {
        let raw = raw.as_bytes().to_vec();
        return Body::JsonRaw(raw);
    }
    if let Some(path) = &items.file_body {
        let content = read_file_bytes(path);
        let ct = crate::mime::mime_type_or_default(path);
        return Body::File(content, ct.to_string());
    }
    match request_type {
        Type::Json => {
            if let Some(stdin) = stdin_body {
                return Body::JsonRaw(stdin);
            }
            let mut root = serde_json::Value::Object(serde_json::Map::new());
            for (key, value) in &items.data {
                let parts = match parse_path(key) {
                    Ok(p) => p,
                    Err(e) => crate::print::path_error(key, e),
                };
                if let Err(e) = crate::to_json::set(&mut root, &parts, value.clone()) {
                    crate::print::set_error(key, &parts, e);
                }
            }
            Body::Json(root)
        }
        Type::Form => {
            let mut pairs = vec![];
            for (key, value) in &items.data {
                match value {
                    serde_json::Value::String(s) => pairs.push((key.clone(), s.clone())),
                    serde_json::Value::Null => pairs.push((key.clone(), String::new())),
                    _ => user_error("JSON values are not supported in Form fields"),
                }
            }
            Body::Form(pairs)
        }
        Type::Multipart => {
            let mut parts = vec![];
            for (key, value) in &items.data {
                let s = match value {
                    serde_json::Value::String(s) => s.clone(),
                    serde_json::Value::Null => String::new(),
                    _ => user_error("JSON values are not supported in Form fields"),
                };
                parts.push(Part { name: key.clone(), filename: None, mime: None, content: s.into_bytes() });
            }
            for (key, filename, mime, name) in &items.files {
                let content = read_file_bytes(filename);
                let m = match mime {
                    Some(m) => Some(m.clone()),
                    None => Some(crate::mime::mime_type_or_default(filename).to_string()),
                };
                let m = match m {
                    Some(m) => {
                        if !m.contains('/') {
                            user_error(&format!("builder error"));
                        }
                        Some(m)
                    }
                    None => None,
                };
                parts.push(Part {
                    name: key.clone(),
                    filename: Some(name.clone().unwrap_or_else(|| basename(filename))),
                    mime: m,
                    content,
                });
            }
            Body::Multipart(parts, new_boundary())
        }
        Type::None => Body::None,
    }
}

fn basename(path: &str) -> String {
    std::path::Path::new(path)
        .file_name()
        .map(|f| f.to_string_lossy().to_string())
        .unwrap_or_else(|| path.to_string())
}

pub fn build_headers(
    cli: &crate::cli::Cli,
    body: &Body,
    request_type: Type,
    items: &Items,
    url: &Url,
) -> Headers {
    let mut h = Headers::new();

    // Authorization from the URL userinfo
    if let Some((user, pass)) = url_password(url) {
        let creds = match pass {
            Some(p) => format!("{}:{}", user, p),
            None => format!("{}:", user),
        };
        h.insert("authorization", &format!("Basic {}", crate::utils::b64(creds.as_bytes())));
    }

    // Default headers
    if !items.headers.iter().any(|(k, v)| k.eq_ignore_ascii_case("accept-encoding") && v.is_none()) {
        h.insert("accept-encoding", default_accept_encoding(cli));
    }
    if !items.headers.iter().any(|(k, v)| k.eq_ignore_ascii_case("user-agent") && v.is_none()) {
        h.insert("user-agent", &format!("{}/{}", crate::PROGRAM, crate::args::VERSION));
    }
    if !items.headers.iter().any(|(k, v)| k.eq_ignore_ascii_case("connection") && v.is_none()) {
        h.insert("connection", "keep-alive");
    }

    let is_json = matches!(request_type, Type::Json);
    if is_json {
        // The Accept header is only omitted if the user provided one.
        if !items.headers.iter().any(|(k, _)| k.eq_ignore_ascii_case("accept")) {
            h.insert("accept", "application/json, */*;q=0.5");
        }
        if let Some(ct) = body.content_type() {
            h.insert("content-type", &ct);
        }
    } else if request_type != Type::None {
        if let Some(ct) = body.content_type() {
            h.insert("content-type", &ct);
        }
    }

    // Authorization from --auth / --bearer
    if let Some(value) = auth_header_value(cli) {
        h.append("authorization", &value);
    }

    // User headers
    let mut seen: Vec<String> = vec![];
    for (name, value) in &items.headers {
        let name = name.to_ascii_lowercase();
        if !crate::utils::valid_header_name(&name) {
            user_error("invalid HTTP header name");
        }
        match value {
            Some(v) => {
                if seen.contains(&name) {
                    h.append(&name, v);
                } else {
                    h.insert(&name, v);
                    seen.push(name.clone());
                }
            }
            None => {
                h.remove(&name);
            }
        }
    }

    // Trailing Accept header for non-JSON requests
    if !is_json {
        if !items.headers.iter().any(|(k, _)| k.eq_ignore_ascii_case("accept")) {
            h.insert("accept", "*/*");
        }
    }

    let _ = url;
    h
}

fn default_accept_encoding(cli: &crate::cli::Cli) -> &'static str {
    if cli.download {
        "identity"
    } else {
        "gzip, deflate, br, zstd"
    }
}

fn auth_header_value(cli: &crate::cli::Cli) -> Option<String> {
    if let Some(token) = &cli.bearer {
        return Some(format!("Bearer {}", token));
    }
    let creds = cli.auth.as_ref()?;
    let t = cli.auth_type.as_deref().unwrap_or("basic");
    match t {
        "bearer" => Some(format!("Bearer {}", creds)),
        _ => {
            let (user, pass) = split_auth(creds);
            Some(format!("Basic {}", crate::utils::b64(format!("{}:{}", user, pass).as_bytes())))
        }
    }
}

pub fn split_auth(creds: &str) -> (String, String) {
    match creds.split_once(':') {
        Some((u, p)) => (u.to_string(), p.to_string()),
        None => (creds.to_string(), String::new()),
    }
}

pub fn url_password(url: &Url) -> Option<(String, Option<String>)> {
    if url.username().is_empty() {
        return None;
    }
    let user = url.username().to_string();
    let pass = url.password().map(|p| p.to_string());
    Some((user, pass))
}
