//! Building and printing HTTP requests from the command line arguments.

use clap::{ErrorKind};
use std::io::Write;
use std::io::Read;
use url::Url;

use crate::body::{new_boundary, Body, Part};
use crate::headers::Headers;
use crate::request_items::{parse, RequestItem};
use crate::to_json::{parse_path, PathPart};

pub struct Request {
    pub method: String,
    pub url: Url,
    pub headers: Headers,
    pub body: Body,
}

pub struct Items {
    pub query: Vec<(String, String)>,
    pub data: Vec<(String, serde_json::Value)>,
    pub headers: Vec<(String, Option<String>)>,
    pub files: Vec<(String, String, Option<String>, Option<String>)>,
    pub file_body: Option<String>,
}

pub fn user_error(msg: &str) -> ! {
    eprintln!("{}: error: {}", crate::PROGRAM, msg);
    std::process::exit(1)
}

fn clap_error_fresh(msg: String, kind: ErrorKind) -> ! {
    let mut cmd = crate::args::build_command(crate::PROGRAM);
    cmd.build();
    cmd.error(kind, msg).exit()
}

fn cmd_error(cmd: &clap::Command, msg: String, kind: ErrorKind) -> ! {
    let mut c = cmd.clone();
    c.build();
    c.error(kind, msg).exit()
}

fn parse_json_value(s: &str, item: &str, cmd: &clap::Command) -> serde_json::Value {
    match serde_json::from_str::<serde_json::Value>(s) {
        Ok(v) => v,
        Err(e) => {
            let mut c = cmd.clone();
            c.build();
            c.error(ErrorKind::InvalidValue, format!("Invalid value for '[REQUEST_ITEM]...': {:?} {}", item, e)).exit();
        }
    }
}

/// Parse and validate all request items.
pub fn parse_items(items: &[String], cmd: &clap::Command) -> Items {
    let mut query = vec![];
    let mut data = vec![];
    let mut headers = vec![];
    let mut files = vec![];
    let mut file_body = None;

    for item in items {
        match parse(item) {
            Ok(RequestItem::QueryString(k, v)) => {
                let v = if let Some(path) = v.strip_prefix('@') { read_file(path, item, cmd) } else { v };
                query.push((k, v));
            }
            Ok(RequestItem::DataField(k, v, literal)) => {
                if let Some(path) = v.strip_prefix('@') {
                    let content = read_file(path, item, cmd);
                    if literal {
                        data.push((k, parse_json_value(&content, item, cmd)));
                    } else {
                        data.push((k, serde_json::Value::String(content)));
                    }
                } else if literal {
                    data.push((k, parse_json_value(&v, item, cmd)));
                } else {
                    data.push((k, serde_json::Value::String(v)));
                }
            }
            Ok(RequestItem::FileField { key, filename, mime, name }) => {
                if let Some(m) = &mime {
                    if !m.contains('/') {
                        let _ = user_error("builder error");
                    }
                }
                files.push((key, filename, mime, name));
            }
            Ok(RequestItem::FileBody(f)) => file_body = Some(f),
            Ok(RequestItem::Header(k, v)) => {
                let v = match v {
                    Some(v) => {
                        if let Some(path) = v.strip_prefix('@') {
                            Some(read_file(path, item, cmd))
                        } else {
                            Some(v)
                        }
                    }
                    None => None,
                };
                headers.push((k, v));
            }
            Err(()) => {
                let mut c = cmd.clone();
                c.build();
                c.error(ErrorKind::InvalidValue, format!("Invalid value for '[REQUEST_ITEM]...': {:?}", item)).exit();
            }
        }
    }
    Items { query, data, headers, files, file_body }
}

fn read_file(path: &str, _item: &str, _cmd: &clap::Command) -> String {
    match std::fs::read(path) {
        Ok(b) => String::from_utf_lossy(&b).to_string(),
        Err(e) => {
            let _ = e;
            eprintln!("{}: error: No such file or directory (os error 2)", crate::PROGRAM);
            std::process::exit(1)
        }
    }
}

fn read_file_bytes(path: &str) -> Vec<u8> {
    match std::fs::read(path) {
        Ok(b) => b,
        Err(_) => {
            eprintln!("{}: error: No such file or directory (os error 2)", crate::PROGRAM);
            std::process::exit(1)
        }
    }
}

/// Build the complete request from the CLI arguments.
pub fn build(cli: &crate::cli::Cli, bin_name: &str, cmd: &clap::Command) -> Request {
    let mut cmd_mut = cmd.clone();
    cmd_mut.build();

    // 1. Split the first positional into a method and a URL.
    let first = cli.url.clone();
    let rest = &cli.request_items;
    let (method, url_str, rest): (Option<String>, String, Vec<String>) =
        if crate::cli::is_http_method(&first) {
            if rest.is_empty() {
                cmd_error(&cmd_mut, "Missing <URL>".to_string(), ErrorKind::MissingSubcommand);
            }
            (Some(first.to_uppercase()), rest[0].clone(), rest[1..].to_vec())
        } else {
            (None, first.clone(), rest.clone())
        };

    // 2. Parse the request items.
    let items = parse_items(rest, cmd);

    // 3. Expand and parse the URL.
    let scheme = crate::url::default_scheme(
        cli.default_scheme.as_deref(),
        cli.https || cli.default_https(bin_name),
        bin_name,
    );
    let expanded = crate::url::expand_url(&url_str, &scheme);
    let mut url = match crate::url::parse(&expanded) {
        Ok(u) => u,
        Err(e) => cmd_error(&cmd_mut, format!("Invalid <URL>: {}", e), ErrorKind::InvalidValue),
    };
    url.set_fragment(None);
    crate::url::append_query(&mut url, &items.query);

    // 4. Read the body from stdin if needed.
    let stdin_body: Option<Vec<u8>> = if cli.ignore_stdin || !crate::utils::stdin_is_redirected() {
        None
    } else {
        let mut buf = vec![];
        let _ = std::io::stdin().read_to_end(&mut buf);
        Some(buf)
    };

    // 5. Determine the request type.
    let has_data = !items.data.is_empty();
    let mut request_type = if cli.multipart {
        Type::Multipart
    } else if cli.form {
        Type::Form
    } else if cli.json || has_data || cli.raw.is_some() || stdin_body.is_some() || items.file_body.is_some() {
        Type::Json
    } else {
        Type::None
    };
    if !items.files.is_empty() && matches!(request_type, Type::Form | Type::Multipart) {
        request_type = Type::Multipart;
    }
    if !items.files.is_empty() && request_type == Type::Json {
        user_error("Can't use file fields in JSON mode (perhaps you meant --form?)");
    }

    // 6. Conflicts between raw data sources.
    if let Some(raw) = &cli.raw {
        if has_data {
            clap_error_fresh(
                "Request body (from --raw) and request data (key=value) cannot be mixed.".to_string(),
                ErrorKind::ArgumentConflict,
            );
        }
        if items.file_body.is_some() {
            clap_error_fresh(
                "Request body (from --raw) and request data (key=value) cannot be mixed.".to_string(),
                ErrorKind::ArgumentConflict,
            );
        }
        if stdin_body.is_some() {
            user_error("Request body from stdin and --raw cannot be mixed. Pass --ignore-stdin to ignore standard input.");
        }
    }
    if let Some(f) = &items.file_body {
        if has_data {
            user_error("Request body (from a file) and request data (key=value) cannot be mixed.");
        }
        let _ = f;
    }
    if stdin_body.is_some() && (has_data || !items.files.is_empty()) {
        if request_type == Type::Multipart {
            user_error("Cannot build a multipart request body from stdin");
        }
        user_error("Request body (from stdin) and request data (key=value) cannot be mixed. Pass --ignore-stdin to ignore standard input.");
    }

    // 7. Build the body.
    let body = build_body(cli, &items, stdin_body, request_type, &mut url);

    // 8. Build the headers.
    let headers = build_headers(cli, &body, request_type, &items, &url);

    // 9. Determine the method.
    let method = match method {
        Some(m) => m,
        None => {
            if body.to_bytes().is_some() || matches!(body, Body::Json(_)) {
                "POST".to_string()
            } else {
                "GET".to_string()
            }
        }
    };

    Request { method, url, headers, body }
}

#[derive(PartialEq, Clone, Copy)]
enum Type {
    Json,
    Form,
    Multipart,
    None,
}

fn build_body(
    cli: &crate::cli::Cli,
    items: &Items,
    stdin_body: Option<Vec<u8>>,
    request_type: Type,
    _url: &mut Url,
) -> Body {
    if let Some(raw) = &cli.raw {
        let raw = raw.as_bytes().to_vec();
        return Body::JsonRaw(raw);
    }
    if let Some(path) = &items.file_body {
        let content = read_file_bytes(path);
        let ct = crate::mime::mime_type_or_default(path);
        return Body::File(content, ct.to_string());
    }
    match request_type {
        Type::Json => {
            if let Some(stdin) = stdin_body {
                return Body::JsonRaw(stdin);
            }
            let mut root = serde_json::Value::Object(serde_json::Map::new());
            for (key, value) in &items.data {
