                        }
                        Some(m)
                    }
                    None => None,
                };
                parts.push(Part {
                    name: key.clone(),
                    filename: Some(name.clone().unwrap_or_else(|| basename(filename))),
                    mime: m,
                    content,
                });
            }
            Body::Multipart(parts, new_boundary())
        }
        Type::None => Body::None,
    }
}

fn basename(path: &str) -> String {
    std::path::Path::new(path)
        .file_name()
        .map(|f| f.to_string_lossy().to_string())
        .unwrap_or_else(|| path.to_string())
}

