//! Small helpers: tty detection, base64, header name validation and casing.

use base64::Engine;

pub fn isatty(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

pub fn stdout_is_tty() -> bool {
    isatty(1)
}

pub fn stdin_is_redirected() -> bool {
    isatty(0)
}

pub fn b64(data: &[u8]) -> String {
    base64::engine::general_purpose::STANDARD.encode(data)
}

const TOKEN_CHARS: &[u8] = b"!#$%&'*+-.^_`|~";

pub fn valid_header_name(name: &str) -> bool {
    !name.is_empty()
        && name.bytes().all(|b| {
            b.is_ascii_alphanumeric() || TOKEN_CHARS.contains(&b)
        })
}

/// Title-case a header name: lower case, then capitalise each `-` separated
/// segment.
pub fn title_case(name: &str) -> String {
    let lower = name.to_ascii_lowercase();
    let mut out = String::new();
    let mut start = true;
    for c in lower.chars() {
        if c == '-' {
            out.push('-');
            start = true;
        } else if start {
            out.extend(c.to_uppercase());
            start = false;
        } else {
            out.push(c);
        }
    }
    out
}

/// Format a duration like the reference implementation does.
pub fn format_elapsed(secs: f64) -> String {
    format!("{:.5}s", secs)
}

/// Encode a string for use in a multipart header value.
pub fn quote_multipart(s: &str) -> String {
    s.to_string()
}
