//! JSON serialisation helpers.

pub fn to_compact_string(v: &serde_json::Value) -> String {
    serde_json::to_string(v).unwrap_or_default()
}

pub fn to_pretty_string(v: &serde_json::Value, indent: usize) -> String {
    let mut s = String::new();
    write_value(&mut s, v, 0, indent, true);
    s
}

fn write_value(out: &mut String, v: &serde_json::Value, depth: usize, indent: usize, _pretty: bool) {
    match v {
        serde_json::Value::Null => out.push_str("null"),
        serde_json::Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        serde_json::Value::Number(n) => out.push_str(&n.to_string()),
        serde_json::Value::String(s) => {
            out.push_str(&serde_json::to_string(s).unwrap_or_default());
        }
        serde_json::Value::Array(arr) => {
            if arr.is_empty() {
                out.push_str("[]");
                return;
            }
            out.push_str("[\n");
            for (i, item) in arr.iter().enumerate() {
                if i > 0 {
                    out.push_str(",\n");
                }
                for _ in 0..(depth + 1) * indent {
                    out.push(' ');
                }
                write_value(out, item, depth + 1, indent, true);
            }
            out.push('\n');
            for _ in 0..depth * indent {
                out.push(' ');
            }
            out.push(']');
        }
        serde_json::Value::Object(map) => {
            if map.is_empty() {
                out.push_str("{}");
                return;
            }
            out.push_str("{\n");
            for (i, (k, val)) in map.iter().enumerate() {
                if i > 0 {
                    out.push_str(",\n");
                }
                for _ in 0..(depth + 1) * indent {
                    out.push(' ');
                }
                out.push_str(&serde_json::to_string(k).unwrap_or_default());
                out.push_str(": ");
                write_value(out, val, depth + 1, indent, true);
            }
            out.push('\n');
            for _ in 0..depth * indent {
                out.push(' ');
            }
            out.push('}');
        }
    }
}
