                            indent = n;
                        }
                    }
                    "json.format" => {
                        if let Ok(b) = v.parse::<bool>() {
                            json_format = b;
                        }
                    }
                    "headers.sort" => {
                        if let Ok(b) = v.parse::<bool>() {
                            sort_headers = b;
                        }
                    }
                    _ => {}
                }
            }
        }
    }
    let theme = if colors { Some(theme(cli.style.as_deref().unwrap_or("auto"))) } else { None };
    PrettyOptions { theme, json_format, json_indent: indent, sort_headers }
}

pub struct Printer {
    pub pretty: PrettyOptions,
    pub quiet: usize,
    out: std::io::Stdout,
}

impl Printer {
    pub fn new(pretty: PrettyOptions) -> Printer {
        Printer { pretty, quiet: 0, out: std::io::stdout() }
    }

    fn write(&mut self, s: &str) {
        let _ = self.out.write_all(s.as_bytes());
    }

    fn flush(&mut self) {
        let _ = self.out.flush();
    }

    pub fn print_request_headers(&mut self, method: &str, url: &url::Url, headers: &Headers) {
        let path = url.path();
        let query = url.query().map(|q| format!("?{}", q)).unwrap_or_default();
        self.write(&format!("{} {}{} HTTP/1.1\n", method, path, query));
        let headers = headers.clone();
        let mut headers = headers;
        if self.pretty.sort_headers {
            headers.sort();
        }
        for (name, value) in headers.iter() {
            self.write(&format!("{}: {}\n", crate::utils::title_case(name), value));
        }
        self.write("\n");
    }

    pub fn print_request_body(&mut self, body: &crate::body::Body) {
        let bytes = match body.to_bytes() {
            Some(b) => b,
            None => return,
        };
        let s = match body {
            crate::body::Body::Json(v) if self.pretty.json_format => {
                crate::highlight::to_ansi_regions(&highlight_text(
                    &crate::json::to_pretty_string(v, self.pretty.json_indent) + "\n\n",
                    "application/json",
                    &self.pretty,
                ))
            }
            crate::body::Body::Json(v) => {
                let text = crate::json::to_compact_string(v);
                if self.pretty.theme.is_some() {
                    crate::highlight::to_ansi_regions(&highlight_text(&text, "application/json", &self.pretty))
                } else {
                    String::from_utf_lossy(&bytes).to_string()
                }
            }
            _ => String::from_utf_lossy(&bytes).to_string(),
        };
        self.write(&s);
        self.write("\n\n");
    }

    pub fn print_response_headers(&mut self, version: &str, status: u16, reason: &str, headers: &Headers) {
        self.write(&format!("{} {} {}\n", version, status, reason));
        let mut headers = headers.clone();
        if self.pretty.sort_headers {
            headers.sort();
        }
        for (name, value) in headers.iter() {
            self.write(&format!("{}: {}\n", crate::utils::title_case(name), value));
        }
        self.write("\n");
    }

    pub fn print_response_body(&mut self, body: &[u8], mime: Option<&str>, meta: bool) {
        let text = String::from_utf_lossy(body).to_string();
        let s = if self.pretty.theme.is_some() {
            if let Some(m) = mime {
                crate::highlight::to_ansi_regions(&highlight_text(&text, m, &self.pretty))
            } else {
                text
            }
        } else if self.pretty.json_format {
            if let Some(m) = mime {
                if is_json_mime(m) {
                    match serde_json::from_str::<serde_json::Value>(&text) {
                        Ok(v) => {
                            crate::json::to_pretty_string(&v, self.pretty.json_indent)
                        }
                        Err(_) => text,
                    }
                } else {
                    text
                }
            } else {
                text
            }
        } else {
            text
        };
        self.write(&s);
        if meta {
            self.write("\n");
        }
    }

    pub fn print_response_meta(&mut self, elapsed: f64, addr: &str) {
        self.write(&format!("Elapsed time: {}\n", crate::utils::format_elapsed(elapsed)));
        self.write(&format!("Remote address: {}\n", addr));
        self.write("\n");
    }

    pub fn println_newline(&mut self) {
        self.write("\n");
    }

    pub fn done(&mut self) {
        self.flush();
    }
}

pub fn is_json_mime(m: &str) -> bool {
    m == "application/json" || m.ends_with("+json")
}

fn highlight_text(text: &str, mime: &str, pretty: &PrettyOptions) -> Vec<(crate::highlight::Style, String)> {
    let theme = pretty.theme.clone().unwrap_or_else(|| theme("auto"));
    let _ = mime;
    let _ = text;
    vec![]
}

/// Print a JSON path parsing error and exit.
pub fn path_error(key: &str, e: crate::to_json::PathError) -> ! {
    let mut msg = String::new();
    msg.push_str(&format!("{}: error: {}\n\n", crate::PROGRAM, e.msg));
    msg.push_str(&format!("  {}\n", key));
    if e.pos >= key.chars().count() {
        msg.push_str("  ");
    } else {
        msg.push_str("  ");
    }
    msg.push_str(&" ".repeat(e.pos));
    msg.push_str("^\n");
    eprint!("{}", msg);
    std::process::exit(1)
}

/// Print a JSON type conflict error and exit.
pub fn set_error(key: &str, parts: &[crate::to_json::PathPart], e: crate::to_json::SetError) -> ! {
    let kind = match parts.get(e.segment) {
        Some(crate::to_json::PathPart::Key(_)) => "key",
        _ => "index",
    };
    let required = if kind == "key" { "object" } else { "array" };
    let path = crate::to_json::render_prefix(parts, e.segment);
    let offset = crate::to_json::segment_offset(key, e.segment);
    let mut msg = String::new();
    msg.push_str(&format!(
        "{}: error: Can't perform '{}' based access on '{}' which has a type of '{}' but this operation requires a type of '{}'.\n\n",
        crate::PROGRAM, kind, path, e.actual, required
    ));
    msg.push_str(&format!("  {}\n", key));
    msg.push_str(&format!("  {}^^^\n", " ".repeat(offset)));
    eprint!("{}", msg);
    std::process::exit(1)
}
