pub const RESET: &str = "\x1b[0m";

/// Highlight the given text with the syntax matching `mime`.
pub fn highlight(text: &str, mime: &str, theme: &Theme) -> String {
    let tokens = match syntax_for_mime(mime) {
        Syntax::Json => json_tokens(text, theme),
        Syntax::Html => html_tokens(text, theme, false),
        Syntax::Xml => html_tokens(text, theme, true),
        Syntax::Css => css_tokens(text, theme),
        Syntax::Js => js_tokens(text, theme),
        Syntax::None => return text.to_string(),
    };
    let mut out = String::new();
    for (style, chunk) in tokens {
        out.push_str(&style.to_ansi());
        out.push_str(&chunk);
    }
    out.push_str(RESET);
    out
}

#[derive(PartialEq, Clone, Copy)]
enum Syntax {
    Json,
    Html,
    Xml,
    Css,
    Js,
    None,
}

fn syntax_for_mime(mime: &str) -> Syntax {
    let base = mime.split(';').next().unwrap_or("").trim().to_ascii_lowercase();
    if base == "application/json" || base.ends_with("+json") || base == "text/json" {
        return Syntax::Json;
    }
    if base.ends_with("html") || base == "application/xhtml+xml" {
        return Syntax::Html;
    }
    if base.ends_with("xml") || base == "text/xml" {
        return Syntax::Xml;
    }
    if base == "text/css" {
        return Syntax::Css;
    }
    if base.contains("javascript") || base == "application/ecmascript" || base.ends_with("+js") {
        return Syntax::Js;
    }
    Syntax::None
}

fn split_lines(text: &str) -> Vec<String> {
    let mut out = vec![];
    let mut cur = String::new();
    for c in text.chars() {
        cur.push(c);
        if c == '\n' {
            out.push(std::mem::take(&mut cur));
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

// ---------------------------------------------------------------- JSON -----

pub fn json_tokens(text: &str, theme: &Theme) -> Vec<(Style, String)> {
    let mut out = vec![];
    let mut in_block_comment = false;
    for line in split_lines(text) {
        let (content, newline) = match line.strip_suffix('\n') {
            Some(c) => (c, "\n"),
            None => (line.as_str(), ""),
        };
        let mut regions = json_line(content, theme, &mut in_block_comment);
        if let Some(last) = regions.last_mut() {
            last.1.push_str(newline);
        } else if !newline.is_empty() {
            regions.push((style_for(theme, ""), newline.to_string()));
        }
        for r in regions {
            out.push(r);
        }
    }
    out
}

fn json_line(text: &str, theme: &Theme, in_block_comment: &mut bool) -> Vec<(Style, String)> {
    let chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    let mut out: Vec<(Style, String)> = vec![];
    let mut i = 0usize;
    if *in_block_comment {
        let mut j = 0usize;
        while j + 1 < n && !(chars[j] == '*' && chars[j + 1] == '/') {
            j += 1;
        }
        if j + 1 < n {
            push(&mut out, style_for(theme, "comment.block.jsonkv"), &chars[0..j + 2]);
            *in_block_comment = false;
            i = j + 2;
        } else {
            push(&mut out, style_for(theme, "comment.block.jsonkv"), &chars[0..n]);
            return out;
        }
    }
    while i < n {
        let c = chars[i];
        if c == '/' && chars.get(i + 1) == Some(&'/') {
            push(&mut out, style_for(theme, "comment.single.line.jsonkv"), &chars[i..n]);
            return out;
        }
        if c == '/' && chars.get(i + 1) == Some(&'*') {
            let mut j = i + 2;
            while j + 1 < n && !(chars[j] == '*' && chars[j + 1] == '/') {
                j += 1;
            }
            if j + 1 < n {
                push(&mut out, style_for(theme, "comment.block.jsonkv"), &chars[i..j + 2]);
                i = j + 2;
            } else {
                push(&mut out, style_for(theme, "comment.block.jsonkv"), &chars[i..n]);
                *in_block_comment = true;
                return out;
            }
            continue;
        }
        if c == '"' {
            // Key name: "..." followed by optional whitespace and ':'
            let mut j = i + 1;
            while j < n && chars[j] != '"' && chars[j] != '\\' {
                j += 1;
            }
            if j < n && chars[j] == '"' {
                let mut k = j + 1;
                while k < n && chars[k].is_whitespace() {
                    k += 1;
                }
                if k < n && chars[k] == ':' {
                    push(&mut out, style_for(theme, "keyword.other.name.jsonkv.start"), &chars[i..i + 1]);
                    push(&mut out, style_for(theme, "keyword.other.name.jsonkv"), &chars[i + 1..j]);
                    push(&mut out, style_for(theme, "keyword.other.name.jsonkv.end"), &chars[j..j + 1]);
                    i = j + 1;
                    continue;
                }
            }
            // String value
            push(&mut out, style_for(theme, "string.quoted.jsonkv"), &chars[i..i + 1]);
            i += 1;
            let mut start = i;
            while i < n {
                if chars[i] == '\\' && i + 1 < n && "tnr\"".contains(chars[i + 1]) {
                    if start < i {
                        push(&mut out, style_for(theme, "string.quoted.jsonkv"), &chars[start..i]);
                    }
                    push(&mut out, style_for(theme, "constant.character.escape.jsonkv"), &chars[i..i + 2]);
                    i += 2;
                    start = i;
                    continue;
                }
                if chars[i] == '"' {
                    i += 1;
                    break;
                }
                i += 1;
            }
            if start < i {
                push(&mut out, style_for(theme, "string.quoted.jsonkv"), &chars[start..i]);
            }
            continue;
        }
        if c.is_ascii_digit() {
            let mut j = i;
            let mut saw_dot = false;
            while j < n {
                if chars[j].is_ascii_digit() {
                    j += 1;
                } else if chars[j] == '.' && !saw_dot {
                    saw_dot = true;
                    j += 1;
                } else {
                    break;
                }
            }
            // The regex is \d+(?:.\d+)?: a trailing dot without digits does not match
            let end = if saw_dot && (j >= n || !chars[j - 1].is_ascii_digit()) { j - 1 } else { j };
            push(&mut out, style_for(theme, "constant.numeric.jsonkv"), &chars[i..end]);
            i = end;
            continue;
        }
        if match_word(&chars, i, "true") {
            push(&mut out, style_for(theme, "constant.language.boolean.jsonkv"), &chars[i..i + 4]);
            i += 4;
            continue;
        }
        if match_word(&chars, i, "false") {
            push(&mut out, style_for(theme, "constant.language.boolean.jsonkv"), &chars[i..i + 5]);
            i += 5;
            continue;
        }
        if match_word(&chars, i, "null") {
            push(&mut out, style_for(theme, "constant.language.null.jsonkv"), &chars[i..i + 4]);
            i += 4;
            continue;
        }
        push(&mut out, style_for(theme, ""), &chars[i..i + 1]);
        i += 1;
    }
    out
}

fn match_word(chars: &[char], i: usize, word: &str) -> bool {
    let w: Vec<char> = word.chars().collect();
    if i + w.len() > chars.len() {
        return false;
    }
    for (k, wc) in w.iter().enumerate() {
        if chars[i + k] != *wc {
            return false;
        }
    }
    // Must not be immediately followed by more word characters
    if let Some(c) = chars.get(i + w.len()) {
        if c.is_alphanumeric() || *c == '_' {
            return false;
        }
    }
    true
}

fn push(out: &mut Vec<(Style, String)>, style: Style, chars: &[char]) {
    if chars.is_empty() {
        return;
    }
    let text: String = chars.iter().collect();
    if let Some(last) = out.last_mut() {
        if last.0 == style {
            last.1.push_str(&text);
            return;
        }
    }
    out.push((style, text));
}

// ---------------------------------------------------------- HTML / XML -----

pub fn html_tokens(text: &str, theme: &Theme, xml: bool) -> Vec<(Style, String)> {
    let _ = xml;
    let mut out = vec![];
    let mut in_comment = false;
    for line in split_lines(text) {
        let (content, newline) = match line.strip_suffix('\n') {
            Some(c) => (c, "\n"),
            None => (line.as_str(), ""),
        };
        let chars: Vec<char> = content.chars().collect();
        let n = chars.len();
        let mut i = 0usize;
        if in_comment {
            let mut j = 0usize;
            while j + 2 < n && !(chars[j] == '-' && chars[j + 1] == '-' && chars[j + 2] == '>') {
                j += 1;
            }
            if j + 2 < n {
                push(&mut out, style_for(theme, "comment.block"), &chars[0..j + 3]);
                i = j + 3;
                in_comment = false;
            } else {
                push(&mut out, style_for(theme, "comment.block"), &chars[0..n]);
                push_newline(&mut out, theme, newline);
                continue;
            }
        }
        while i < n {
            let c = chars[i];
            if c == '<' {
                if chars[i + 1..].starts_with(&['!', '-', '-']) {
                    in_comment = true;
                    break;
                }
                // tag
                let mut j = i + 1;
                if j < n && chars[j] == '/' {
                    j += 1;
                }
                let name_start = j;
                while j < n && !chars[j].is_whitespace() && chars[j] != '>' && chars[j] != '/' {
                    j += 1;
                }
                push(&mut out, style_for(theme, ""), &chars[i..name_start]);
                if j > name_start {
                    push(&mut out, style_for(theme, "entity.name.tag"), &chars[name_start..j]);
                }
                // attributes until '>' or EOF
                let mut k = j;
                while k < n && chars[k] != '>' {
                    if chars[k].is_whitespace() {
                        push(&mut out, style_for(theme, ""), &chars[k..k + 1]);
                        k += 1;
                        continue;
                    }
                    let a_start = k;
                    while k < n && !chars[k].is_whitespace() && chars[k] != '=' && chars[k] != '>' {
                        k += 1;
                    }
                    push(&mut out, style_for(theme, "entity.other.attribute-name"), &chars[a_start..k]);
                    if k < n && chars[k] == '=' {
                        push(&mut out, style_for(theme, ""), &chars[k..k + 1]);
                        k += 1;
                        if k < n && (chars[k] == '"' || chars[k] == '\'') {
                            let q = chars[k];
                            push(&mut out, style_for(theme, "string.quoted"), &chars[k..k + 1]);
                            k += 1;
                            let vs = k;
                            while k < n && chars[k] != q {
                                k += 1;
                            }
                            push(&mut out, style_for(theme, "string.quoted"), &chars[vs..k]);
                            if k < n {
                                push(&mut out, style_for(theme, "string.quoted"), &chars[k..k + 1]);
                                k += 1;
                            }
                        }
                    }
                }
                if k < n {
                    push(&mut out, style_for(theme, ""), &chars[k..k + 1]);
                    i = k + 1;
                } else {
                    i = n;
                }
                continue;
            }
            push(&mut out, style_for(theme, ""), &chars[i..i + 1]);
            i += 1;
        }
        push_newline(&mut out, theme, newline);
    }
    out
}

fn push_newline(out: &mut Vec<(Style, String)>, theme: &Theme, newline: &str) {
    if newline.is_empty() {
        return;
    }
    push(out, style_for(theme, ""), newline);
}

// ---------------------------------------------------------------- CSS -----

pub fn css_tokens(text: &str, theme: &Theme) -> Vec<(Style, String)> {
    let mut out = vec![];
    for line in split_lines(text) {
        let (content, newline) = match line.strip_suffix('\n') {
            Some(c) => (c, "\n"),
            None => (line.as_str(), ""),
        };
        let chars: Vec<char> = content.chars().collect();
        let n = chars.len();
        let mut i = 0usize;
        while i < n {
            let c = chars[i];
            if c.is_alphabetic() || c == '_' || c == '-' || c == '\\' || !c.is_ascii() {
                let start = i;
                while i < n && (chars[i].is_alphanumeric() || chars[i] == '-' || chars[i] == '_' || chars[i] == '\\') {
                    i += 1;
                }
                let word: String = chars[start..i].iter().collect();
                // Selector or property: heuristically colour selectors
                let scope = if word.contains('.') || word == &content[..content.len().min(word.len())] {
                    "entity.name.tag.css"
                } else {
                    "entity.other.attribute-name.css"
                };
                let _ = scope;
                push(&mut out, style_for(theme, "entity.name.tag"), &chars[start..i]);
                continue;
            }
            if c.is_ascii_digit() {
                let start = i;
                while i < n && (chars[i].is_ascii_digit() || chars[i] == '.' || chars[i] == '%') {
                    i += 1;
                }
                push(&mut out, style_for(theme, "constant.numeric"), &chars[start..i]);
                continue;
            }
            push(&mut out, style_for(theme, ""), &chars[i..i + 1]);
            i += 1;
        }
        push_newline(&mut out, theme, newline);
    }
    out
}

// ---------------------------------------------------------------- JS -----

pub fn js_tokens(text: &str, theme: &Theme) -> Vec<(Style, String)> {
    let mut out = vec![];
    for line in split_lines(text) {
        let (content, newline) = match line.strip_suffix('\n') {
            Some(c) => (c, "\n"),
            None => (line.as_str(), ""),
        };
        let chars: Vec<char> = content.chars().collect();
        let n = chars.len();
        let mut i = 0usize;
        while i < n {
            let c = chars[i];
            if c.is_ascii_digit() {
                let start = i;
                while i < n && (chars[i].is_ascii_digit() || chars[i] == '.') {
                    i += 1;
                }
                push(&mut out, style_for(theme, "constant.numeric"), &chars[start..i]);
                continue;
            }
            if c == '"' || c == '\'' || c == '`' {
                let start = i;
                i += 1;
                while i < n && chars[i] != c {
                    i += 1;
                }
                if i < n {
                    i += 1;
                }
                push(&mut out, style_for(theme, "string.quoted"), &chars[start..i]);
                continue;
            }
            if c == '/' && i + 1 < n && chars[i + 1] == '/' {
                push(&mut out, style_for(theme, "comment.line"), &chars[i..n]);
                break;
            }
            push(&mut out, style_for(theme, ""), &chars[i..i + 1]);
            i += 1;
        }
        push_newline(&mut out, theme, newline);
    }
    out
}
