//! A minimal syntax highlighter reproducing the output of the reference
//! implementation.

#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Style {
    pub fg: Option<u8>,
    pub underline: bool,
    pub bold: bool,
    pub italic: bool,
}

impl Style {
    pub const fn plain() -> Style {
        Style { fg: None, underline: false, bold: false, italic: false }
    }
    pub const fn fg(c: u8) -> Style {
        Style { fg: Some(c), underline: false, bold: false, italic: false }
    }
    pub const fn fg_underline(c: u8) -> Style {
        Style { fg: Some(c), underline: true, bold: false, italic: false }
    }
    pub fn to_ansi(&self) -> String {
        let mut s = String::from("\x1b[0m");
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if self.italic {
            s.push_str("\x1b[3m");
        }
        if self.underline {
            s.push_str("\x1b[4m");
        }
        if let Some(c) = self.fg {
            s.push_str(&ansi_fg(c));
        }
        s
    }
}

pub fn ansi_fg(c: u8) -> String {
    if c < 8 {
        format!("\x1b[{}m", 30 + c)
    } else if c == 8 {
        "\x1b[90m".to_string()
    } else {
        format!("\x1b[38;5;{}m", c)
    }
}

pub struct Theme {
    /// (scope prefix, style) pairs, most specific scope first
    pub rules: Vec<(&'static str, Style)>,
    pub default: Style,
}

/// syntect-style scope matching: the theme rule `constant.numeric` matches
/// `constant.numeric.jsonkv`.
fn scope_matches(scope: &str, prefix: &str) -> bool {
    if prefix.is_empty() {
        return true;
    }
    let mut rest = scope;
    loop {
        if rest == prefix {
            return true;
        }
        match rest.rfind('.') {
            Some(i) => rest = &rest[..i],
            None => return false,
        }
    }
}

pub fn style_for(theme: &Theme, scope: &str) -> Style {
    for (prefix, style) in &theme.rules {
        if scope_matches(scope, prefix) {
            return *style;
        }
    }
    theme.default
}

pub fn theme(name: &str) -> Theme {
    match name {
        "solarized" => Theme {
            rules: vec![
                ("entity.other.attribute-name", Style::fg(245)),
                ("entity.name.tag.doctype", Style::fg(64)),
                ("entity.name.tag", Style::fg(33)),
                ("support.variable.http", Style::fg(245)),
                ("string.other.http", Style::fg(37)),
                ("keyword.reason.http", Style::fg(136)),
                ("keyword.other.http", Style::fg(33)),
