}

pub struct Theme {
    /// (scope prefix, style) pairs, most specific scope first
    pub rules: Vec<(&'static str, Style)>,
    pub default: Style,
}

/// syntect-style scope matching: the theme rule `constant.numeric` matches
/// `constant.numeric.jsonkv`.
fn scope_matches(scope: &str, prefix: &str) -> bool {
    if prefix.is_empty() {
        return true;
    }
    let mut rest = scope;
    loop {
        if rest == prefix {
            return true;
        }
        match rest.rfind('.') {
            Some(i) => rest = &rest[..i],
            None => return false,
        }
    }
}

pub fn style_for(theme: &Theme, scope: &str) -> Style {
    for (prefix, style) in &theme.rules {
        if scope_matches(scope, prefix) {
            return *style;
        }
    }
    theme.default
}

