    let mut s = format!("--{}", a.long);
    if let Some(c) = a.short {
        s.push_str(&format!("(-{})", c));
    }
    if let Some(val) = a.val {
        if !ARGS.iter().any(|x| x.id == a.id && x.pv.is_empty()) {
            s.push_str(": string");
        } else {
            s.push_str(&format!(": string@\"nu-complete {} {}\"", bin, a.id));
        }
    }
    s
}

pub fn generate(bin: &str) {
    // Argument ids that complete with possible values, in declaration order.
    let mut defs: Vec<(&crate::args::ArgSpec, Vec<String>)> = vec![];
    for a in ARGS {
        if !a.pv.is_empty() && a.val.is_some() && !a.hidden && a.id != "help" && a.id != "version" {
            defs.push((a, a.pv.iter().map(|s| s.to_string()).collect()));
        }
    }
    let mut out = String::from("module completions {\n\n");
    for (a, pvs) in &defs {
        out.push_str(&format!("  def \"nu-complete {} {}\" [] {{\n", bin, a.id));
        out.push_str("    [ ");
        out.push_str(&pvs.iter().map(|v| format!("{:?}", v)).collect::<Vec<_>>().join(" "));
        out.push_str(" ]\n  }\n\n");
    }
    out.push_str(&format!("  # xh is a friendly and fast tool for sending HTTP requests\n"));
    out.push_str(&format!("  export extern {} [\n", bin));
    let mut entries: Vec<(String, String)> = vec![];
    for a in ARGS {
        if a.id == "raw_method_or_url" || a.id == "raw_rest_args" {
            continue;
        }
        if a.action == Act::Help || a.action == Act::Version {
            // handled below
        }
        let s = spec(a, bin);
        let s = if a.val.is_some() {
            if a.id == "output" || a.id == "cert" || a.id == "cert_key" || a.id == "unix_socket" {
                s.replace(": string", ": path")
            } else if !a.pv.is_empty() {
                s
            } else {
                s.replace(": string", ": string")
            }
        } else {
            s
        };
        entries.push((s, a.help.to_string()));
    }
    // positionals
    entries.push(("raw_method_or_url: string".to_string(), crate::args::HELP_URL.to_string()));
    entries.push(("...raw_rest_args: string".to_string(), crate::args::HELP_ITEMS.to_string()));
    for (s, help) in &entries {
        if help.is_empty() {
            out.push_str(&format!("    {}\n", s));
        } else {
            let pad = if s.chars().count() < 26 { 26 - s.chars().count() } else { 1 };
            out.push_str(&format!("    {}{}# {}\n", s, " ".repeat(pad), help));
        }
    }
    out.push_str("  ]\n\n}\n\nexport use completions *\n");
    print!("{}", out);
}
RSEOF
echo ok"}

