//! Nushell completion generation.

use crate::args::{ARGS, Act};

fn value_hint_path(a: &crate::args::ArgSpec) -> bool {
    matches!(a.id, "output" | "cert" | "cert_key" | "unix_socket")
}

pub fn generate(bin: &str) {
    let mut out = String::from("module completions {\n\n");
    for a in ARGS {
        if a.pv.is_empty() || a.val.is_none() || a.id.starts_with("no_") {
            continue;
        }
        if a.id == "help" || a.id == "version" {
            continue;
        }
        out.push_str(&format!("  def \"nu-complete {} {}\" [] {{\n", bin, a.id));
        out.push_str("    [ ");
        out.push_str(&a.pv.iter().map(|v| format!("{:?}", v)).collect::<Vec<_>>().join(" "));
        out.push_str(" ]\n  }\n\n");
    }
    out.push_str("  # xh is a friendly and fast tool for sending HTTP requests\n");
    out.push_str(&format!("  export extern {} [\n", bin));
    for a in ARGS {
        if a.id == "raw_method_or_url" || a.id == "raw_rest_args" {
            continue;
        }
        let mut s = format!("--{}", a.long);
        if let Some(c) = a.short {
            s.push_str(&format!("(-{})", c));
        }
        if let Some(_val) = a.val {
            if a.pv.is_empty() {
                s.push_str(if value_hint_path(a) { ": path" } else { ": string" });
            } else {
                s.push_str(&format!(": string@\"nu-complete {} {}\"", bin, a.id));
            }
        }
        let help = a.help;
        if help.is_empty() {
            out.push_str(&format!("    {}\n", s));
        } else {
            let pad = if s.chars().count() < 26 { 26 - s.chars().count() } else { 1 };
            out.push_str(&format!("    {}{}# {}\n", s, " ".repeat(pad), help));
        }
    }
    out.push_str(&format!("    {}{}# {}\n", "raw_method_or_url: string", " ", crate::args::HELP_URL));
    out.push_str(&format!("    {}{}# {}\n", "...raw_rest_args: string", "   ", crate::args::HELP_ITEMS));
    out.push_str("  ]\n\n}\n\nexport use completions *\n");
    print!("{}", out);
}
RSEOF
