//! Translation of a request into an equivalent curl command line.

use crate::body::Body;
use crate::headers::Headers;

const SAFE_CHARS: &str = "!#%+,-./:@_~";

fn is_safe(c: char) -> bool {
    c.is_ascii_alphanumeric() || SAFE_CHARS.contains(c)
}

pub fn quote(arg: &str) -> String {
    if !arg.is_empty() && arg.chars().all(is_safe) {
        return arg.to_string();
    }
    if arg.contains('\'') {
        return format!("\"{}\"", arg);
    }
    if arg.chars().any(|c| c.is_control() && !matches!(c, '\t' | '\n' | '\r')) {
        return dollar_quote(arg);
    }
    format!("'{}'", arg)
}

fn dollar_quote(arg: &str) -> String {
    let mut groups: Vec<String> = vec![];
    let mut cur = String::new();
    let chars: Vec<char> = arg.chars().collect();
    for (i, c) in chars.iter().enumerate() {
        match c {
            '\t' => cur.push_str("\\t"),
            '\n' => cur.push_str("\\n"),
            '\r' => cur.push_str("\\r"),
            '\'' => cur.push_str("\\'"),
            c if c.is_control() => {
                cur.push_str(&format!("\\x{:02X}", *c as u32));
                let next_is_alnum = chars.get(i + 1).map(|c| c.is_ascii_alphanumeric()).unwrap_or(false);
                if next_is_alnum {
                    groups.push(std::mem::take(&mut cur));
                }
            }
            c => cur.push(*c),
        }
    }
    if !cur.is_empty() {
        groups.push(cur);
    }
    if groups.is_empty() {
        groups.push(String::new());
    }
    groups.iter().map(|g| format!("$'{}'", g)).collect::<Vec<_>>().join("")
}

pub fn to_curl(cli: &crate::cli::Cli, req: &crate::request::Request) -> String {
    let mut out = String::new();

    // Proxies
    let mut env_prefix = String::new();
    for p in &cli.proxy {
        if let Some((proto, url)) = p.split_once(':') {
            if proto == "all" {
                out.push_str(&format!("-x {} ", url));
            } else {
                let var = match proto {
                    "https" => "https_proxy",
                    _ => "http_proxy",
                };
                env_prefix.push_str(&format!("{}={} ", var, normalize_proxy_url(url)));
            }
        }
    }
    if !env_prefix.is_empty() {
        out.insert_str(0, &env_prefix);
    }

    let long = cli.curl_long;
    let mut cmd = String::from("curl ");
    if cli.quiet > 0 {
        cmd.push_str("-s ");
    }
    if cli.stream {
        cmd.push_str("-N ");
    }
    if cli.check_status || cli.download {
        cmd.push_str("-f ");
    }
    if cli.follow || cli.download {
        cmd.push_str("-L ");
    }
    if let Some(n) = cli.max_redirects {
        cmd.push_str(&format!("{} {} ", long_flag(long, "--max-redirs", "-l"), n));
    }
    if let Some(o) = &cli.output {
        cmd.push_str(&format!("{} {} ", long_flag(long, "--output", "-o"), o));
    } else if cli.download {
        cmd.push_str("-O ");
    }
    if cli.resume {
        cmd.push_str(&format!("{} - ", long_flag(long, "--continue-at", "-C")));
    }
    if let Some(v) = &cli.verify {
        let v = v.to_ascii_lowercase();
        if v == "no" || v == "false" {
            cmd.push_str(&format!("{} ", long_flag(long, "--insecure", "-k")));
        } else if v != "yes" && v != "true" {
            cmd.push_str(&format!("{} {} ", long_flag(long, "--cacert", "--cacert"), v));
        }
    }
    if let Some(c) = &cli.cert {
        cmd.push_str(&format!("{} {} ", long_flag(long, "--cert", "-E"), c));
    }
    if let Some(c) = &cli.cert_key {
        cmd.push_str(&format!("{} {} ", long_flag(long, "--key", "--key"), c));
    }
    if let Some(v) = &cli.ssl {
        let (flag, max) = match v.as_str() {
            "tls1" => ("--tlsv1.0", "1.0"),
            "tls1.1" => ("--tlsv1.1", "1.1"),
            "tls1.2" => ("--tlsv1.2", "1.2"),
            "tls1.3" => ("--tlsv1.3", "1.3"),
            _ => ("", ""),
        };
        if !flag.is_empty() {
            cmd.push_str(&format!("{} {} {} {} ", flag, long_flag(long, "--tls-max", "--tls-max"), max, ""));
        }
    }
    if let Some(t) = cli.timeout {
        cmd.push_str(&format!("{} {} ", long_flag(long, "--max-time", "--max-time"), crate::utils::format_curl_time(t)));
    }
    if let Some(v) = &cli.http_version {
        let f = match v.as_str() {
            "1.0" => "--http1.0",
            "1.1" => "--http1.1",
            "2" => "--http2",
            "2-prior-knowledge" => "--http2-prior-knowledge",
            "3-prior-knowledge" => "--http3-only",
            _ => "",
        };
        cmd.push_str(&format!("{} ", f));
    }

    // URL
    cmd.push_str(&format!("{} ", quote(&req.url.as_str())));

    if cli.ipv4 && !cli.ipv6 {
        cmd.push_str("-4 ");
    } else if cli.ipv6 && !cli.ipv4 {
        cmd.push_str("-6 ");
    }
    for i in &cli.interface {
        cmd.push_str(&format!("{} {} ", long_flag(long, "--interface", "--interface"), i));
    }
    if let Some(s) = &cli.unix_socket {
        cmd.push_str(&format!("{} {} ", long_flag(long, "--unix-socket", "--unix-socket"), s));
    }
    for r in &cli.resolve {
        let (host, addr) = r.split_once(':').unwrap_or((r, ""));
        let port = req.url.port_or_known_default().map(|p| p.to_string()).unwrap_or_default();
        cmd.push_str(&format!("{} {}:{}:{} ", long_flag(long, "--resolve", "--resolve"), host, port, addr));
    }

    // Method
    let explicit_method = cli.method.is_some();
    let method = &req.method;
    if explicit_method {
        if method == "HEAD" {
            cmd.push_str("-I ");
        } else if method != "GET" || has_data(cli, req) {
            cmd.push_str(&format!("{} {} ", long_flag(long, "--request", "-X"), method));
        } else {
            cmd.push_str(&format!("{} {} ", long_flag(long, "--request", "-X"), method));
        }
    }

    // User headers
    for (name, value) in req.headers.iter() {
        if is_auto_header(name) {
            continue;
        }
        cmd.push_str(&format!("{} '{}:{}' ", long_flag(long, "--header", "-H"), name, value));
    }

    // Auth
    if let Some(value) = crate::request::auth_header_value_public(cli) {
        if let Some(tok) = value.strip_prefix("Bearer ") {
            cmd.push_str(&format!("{} {} ", long_flag(long, "--oauth2-bearer", "--oauth2-bearer"), tok));
        } else if let Some(b64) = value.strip_prefix("Basic ") {
            let creds = crate::utils::b64_decode(&b64);
            let t = cli.auth_type.as_deref().unwrap_or("basic");
            if t == "digest" {
                cmd.push_str(&format!("{} {} ", long_flag(long, "--digest", "--digest"), ""));
            } else {
                cmd.push_str(&format!("{} ", long_flag(long, "--basic", "--basic")));
            }
            cmd.push_str(&format!("{} {} ", long_flag(long, "--user", "-u"), creds));
        }
    }

    // Body
    match &req.body {
        Body::Form(pairs) => {
            for (k, v) in pairs {
                cmd.push_str(&format!("{} {} ", long_flag(long, "--data-urlencode", "--data-urlencode"), quote(&format!("{}={}", k, v))));
            }
        }
        Body::Multipart(parts, _) => {
            for part in parts {
                let mut spec = format!("{}=", part.name);
                if let Some(f) = &part.filename {
                    spec.push_str(&format!("@{}", f));
                    if let Some(m) = &part.mime {
                        spec.push_str(&format!(";type={}", m));
                    }
                } else {
                    spec.push_str(&String::from_utf_lossy(&part.content));
                    if let Some(m) = &part.mime {
                        spec.push_str(&format!(";type={}", m));
                    }
                }
                cmd.push_str(&format!("-F {} ", quote(&spec)));
            }
        }
        Body::File(_, _) => {
            if let Some(ct) = req.body.content_type() {
                cmd.push_str(&format!("{} '{}: {}' ", long_flag(long, "--header", "-H"), "content-type", ct));
            }
            cmd.push_str(&format!("{} @{} ", long_flag(long, "--data-binary", "--data-binary"), file_path_of(cli)));
        }
        Body::Json(_) | Body::JsonRaw(_) | Body::None => {
            if let Some(ct) = req.body.content_type() {
                cmd.push_str(&format!("{} '{}: {}' ", long_flag(long, "--header", "-H"), "content-type", ct));
            }
            cmd.push_str(&format!("{} '{}: {}' ", long_flag(long, "--header", "-H"), "accept", accept_value(cli, req)));
            if let Some(bytes) = req.body.to_bytes() {
                let is_multipart = false;
                let _ = is_multipart;
                if let crate::body::Body::JsonRaw(_) = req.body {
                    cmd.push_str(&format!("{} {} ", long_flag(long, "--data", "-d"), quote(&String::from_utf_lossy(&bytes))));
                } else {
                    let text = crate::json::to_compact_string(&crate::body::json_value(req.body));
                    cmd.push_str(&format!("{} {} ", long_flag(long, "--data", "-d"), quote(&text)));
                }
            }
        }
    }

    out.push_str(cmd.trim_end());
    out
}

fn long_flag(long: bool, long_name: &str, short_name: &str) -> &'static str {
    if long {
        return long_name;
    }
    short_name
}

fn has_data(_cli: &crate::cli::Cli, _req: &crate::request::Request) -> bool {
    false
}

fn is_auto_header(name: &str) -> bool {
    matches!(name, "accept-encoding" | "user-agent" | "connection" | "content-length" | "host")
}

fn accept_value(_cli: &crate::cli::Cli, _req: &crate::request::Request) -> &'static str {
    "application/json, */*;q=0.5"
}

fn file_path_of(cli: &crate::cli::Cli) -> String {
    cli.url.clone()
}

fn normalize_proxy_url(u: &str) -> String {
    match url::Url::parse(u) {
        Ok(mut url) => {
            url.set_fragment(None);
            url.to_string()
        }
        Err(_) => u.to_string(),
    }
}
RSEOF
echo ok"}

