                    Ok(_) => None,
                    Err(_) => Some(format!("Invalid address '{}'", parts[1])),
                }
            }
        }
        "format_options" => {
            match value.split_once(':') {
                None => Some("Format options consist of a key and a value, separated by a \":\".".to_string()),
                Some((k, v)) => {
                    let ok_val = match k {
                        "json.indent" => v.parse::<usize>().is_ok(),
                        "json.format" | "headers.sort" => {
                            matches!(v, "true" | "false")
                        }
