/// Build the error message for an invalid option value, if it is invalid.
pub fn check_value(id: &str, arg: &str, value: &str) -> Option<String> {
    let msg = match id {
        "timeout" => match value.parse::<f64>() {
            Err(_) => Some("Connection timeout is not a valid number"),
            Ok(t) => {
                if t.is_nan() {
                    Some("Connection timeout is not a valid number")
                } else if t.is_sign_negative() {
                    Some("Connection timeout is negative")
                } else if t.is_infinite() || t >= u64::MAX as f64 {
                    Some("Connection timeout is too big")
                } else {
                    None
                }
            }
        },
        "max_redirects" => match value.parse::<usize>() {
            Ok(_) => None,
            Err(e) => Some(e.to_string()),
        },
        "proxy" => {
            let (proto, url) = match value.split_once(':') {
                Some((p, u)) => (p, u),
                None => (value, ""),
            };
            if !matches!(proto, "http" | "https" | "all") {
                Some(format!("Unknown protocol to set a proxy for: {}", proto))
            } else {
                match url::Url::parse(url) {
                    Ok(_) => None,
                    Err(e) => Some(format!("Invalid proxy URL '{}' for protocol '{}': {}", url, proto, e)),
                }
            }
        }
        "resolve" => {
            let parts: Vec<&str> = value.split(':').collect();
            if parts.len() == 1 {
                Some("Value should be formatted as <HOST>:<ADDRESS>".to_string())
            } else if parts.len() > 2 {
                Some("Value should be formatted as <HOST>:<ADDRESS> (not <HOST>:<PORT>:<ADDRESS>)".to_string())
            } else {
                match parts[1].parse::<std::net::IpAddr>() {
                    Ok(_) => None,
                    Err(_) => Some(format!("Invalid address '{}'", parts[1])),
                }
            }
        }
        "format_options" => match value.split_once(':') {
            None => Some("Format options consist of a key and a value, separated by a \":\".".to_string()),
            Some((k, v)) => {
                let ok_val = match k {
                    "json.indent" => v.parse::<usize>().is_ok(),
                    "json.format" | "headers.sort" => matches!(v, "true" | "false"),
                    _ => true,
                };
                if ok_val {
                    None
                } else {
                    Some(format!("Invalid value '{}' in '{}'", v, value))
                }
            }
        },
        "response_charset" => {
            let lower = value.to_ascii_lowercase();
            if WHATWG_LABELS.contains(&lower.as_str()) {
                None
            } else {
                Some(format!("{} is not a supported encoding, please refer to https://encoding.spec.whatwg.org/#names-and-labels for supported encodings", value))
            }
        }
        _ => None,
    }?;
    Some(format!("invalid value '{}' for '{}': {}", value, arg, msg))
}

pub fn value_error(msg: &str) -> ! {
    eprintln!("error: {}\n\nFor more information, try '--help'.", msg);
    std::process::exit(2)
}

/// The clap display form of each argument that takes a value.
pub fn arg_display(id: &str) -> &'static str {
    match id {
        "timeout" => "--timeout <SEC>",
        "max_redirects" => "--max-redirects <NUM>",
        "proxy" => "--proxy <PROTOCOL:URL>",
        "resolve" => "--resolve <HOST:ADDRESS>",
        "format_options" => "--format-options <FORMAT_OPTIONS>",
        "response_charset" => "--response-charset <ENCODING>",
        _ => "",
    }
}
