/// Scan the raw command line arguments for values that fail validation, in the
/// order they appear.
pub fn collect_value_errors(argv: &[String]) -> Vec<(usize, String)> {
    let mut out: Vec<(usize, String)> = vec![];
    let mut i = 0usize;
    while i < argv.len() {
        let a = &argv[i];
        if i == 0 {
            i += 1;
            continue;
        }
        if a == "--" {
            break;
        }
        if let Some(rest) = a.strip_prefix("--") {
            let (name, inline) = match rest.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (rest.to_string(), None),
            };
            if let Some(spec) = crate::args::ARGS.iter().find(|s| s.long == name) {
                if !spec.val.is_none() && !spec.id.starts_with("no_") {
                    let value = match inline {
                        Some(v) => v,
                        None => argv.get(i + 1).cloned().unwrap_or_default(),
                    };
                    if let Some(msg) = check_value(spec.id, spec.long, &value) {
                        out.push((i, msg));
                    }
                    if inline.is_none() {
                        i += 1;
                    }
                }
            }
        } else if a.len() > 1 && a.starts_with('-') {
            let chars: Vec<char> = a[1..].chars().collect();
            for (k, c) in chars.iter().enumerate() {
                if let Some(spec) = crate::args::ARGS.iter().find(|s| s.short == Some(*c)) {
                    if !spec.val.is_none() && !spec.id.starts_with("no_") {
                        let rest: String = chars[k + 1..].iter().collect();
                        let value = if rest.is_empty() {
                            argv.get(i + 1).cloned().unwrap_or_default()
                        } else if let Some(v) = rest.strip_prefix('=') {
                            v.to_string()
                        } else {
                            rest
                        };
                        if let Some(msg) = check_value(spec.id, spec.long, &value) {
                            out.push((i, msg));
                        }
                        break;
                    }
                }
            }
        }
        i += 1;
    }
    out
}
