//! Translation of a request into an equivalent curl command line.

use crate::body::Body;

const SAFE_CHARS: &str = "!#%+,-./:@_~";

fn is_safe(c: char) -> bool {
    c.is_ascii_alphanumeric() || SAFE_CHARS.contains(c)
}

pub fn quote(arg: &str) -> String {
    if !arg.is_empty() && arg.chars().all(is_safe) {
        return arg.to_string();
    }
    if arg.contains('\'') {
        return format!("\"{}\"", arg);
    }
    if arg.chars().any(|c| c.is_control() && !matches!(c, '\t' | '\n' | '\r')) {
        return dollar_quote(arg);
    }
    format!("'{}'", arg)
}

fn dollar_quote(arg: &str) -> String {
    let mut groups: Vec<String> = vec![];
    let mut cur = String::new();
    let chars: Vec<char> = arg.chars().collect();
    for (i, c) in chars.iter().enumerate() {
        match c {
            '\t' => cur.push_str("\\t"),
            '\n' => cur.push_str("\\n"),
            '\r' => cur.push_str("\\r"),
            '\'' => cur.push_str("\\'"),
            c if c.is_control() => {
                cur.push_str(&format!("\\x{:02X}", *c as u32));
                let next_is_alnum =
                    chars.get(i + 1).map(|c| c.is_ascii_alphanumeric()).unwrap_or(false);
                if next_is_alnum {
                    groups.push(std::mem::take(&mut cur));
                }
            }
            c => cur.push(*c),
        }
    }
    if !cur.is_empty() {
        groups.push(cur);
    }
    if groups.is_empty() {
        groups.push(String::new());
    }
    groups.iter().map(|g| format!("$'{}'", g)).collect::<Vec<_>>().join("")
}

fn lf(long: bool, long_name: &'static str, short_name: &'static str) -> &'static str {
    if long {
        long_name
    } else {
        short_name
    }
}

pub fn print_warnings(cli: &crate::cli::Cli) {
    let mut warnings: Vec<String> = vec![];
    if cli.offline {
        warnings.push("Ignored --offline".to_string());
    }
    if cli.pretty.is_some() {
        warnings.push("Ignored --pretty".to_string());
    }
    if cli.compress > 0 {
        warnings.push("Ignored -x/--compress".to_string());
    }
    if cli.all {
        warnings.push("Ignored --all".to_string());
    }
    if cli.history_print.is_some() {
        warnings.push("Ignored -P/--history-print".to_string());
    }
    if cli.print.is_some() {
        warnings.push("Ignored -p/--print".to_string());
    }
    if cli.body {
        warnings.push("Ignored -b/--body".to_string());
    }
    if cli.session.is_some() || cli.session_read_only.is_some() {
        warnings.push("Ignored --session".to_string());
    }
    for w in warnings {
        eprintln!("Warning: {}", w);
    }
    if !warnings.is_empty() {
        eprintln!();
    }
}

pub fn to_curl(cli: &crate::cli::Cli, req: &crate::request::Request) -> String {
    let long = cli.curl_long;
    let mut env_prefix = String::new();
    let mut parts: Vec<String> = vec![];
    for p in &cli.proxy {
        if let Some((proto, url)) = p.split_once(':') {
            if proto == "all" {
                parts.push(format!("-x {}", quote(url)));
            } else {
                let var = if proto == "https" { "https_proxy" } else { "http_proxy" };
                env_prefix.push_str(&format!("{}={} ", var, normalize_proxy_url(url)));
            }
        }
    }

    if cli.quiet > 0 {
        parts.push("-s".to_string());
    }
    if cli.stream {
        parts.push("-N".to_string());
    }
    if cli.check_status || cli.download {
        parts.push("-f".to_string());
    }
    if cli.follow || cli.download {
        parts.push("-L".to_string());
    }
    if let Some(n) = cli.max_redirects {
        parts.push(format!("{} {}", lf(long, "--max-redirs", "--max-redirs"), n));
    }
    if let Some(o) = &cli.output {
        parts.push(format!("{} {}", lf(long, "--output", "-o"), o));
    } else if cli.download {
        parts.push("-O".to_string());
    }
    if cli.resume {
        parts.push(format!("{} -", lf(long, "--continue-at", "-C")));
    }
    if let Some(v) = &cli.verify {
        let v = v.to_ascii_lowercase();
        if v == "no" || v == "false" {
            parts.push(lf(long, "--insecure", "-k").to_string());
        } else if v != "yes" && v != "true" {
            parts.push(format!("{} {}", lf(long, "--cacert", "--cacert"), v));
        }
    }
    if let Some(c) = &cli.cert {
        parts.push(format!("{} {}", lf(long, "--cert", "-E"), c));
    }
    if let Some(c) = &cli.cert_key {
        parts.push(format!("{} {}", lf(long, "--key", "--key"), c));
    }
    if let Some(v) = &cli.ssl {
        let (flag, max) = match v.as_str() {
            "tls1" => ("--tlsv1.0", "1.0"),
            "tls1.1" => ("--tlsv1.1", "1.1"),
            "tls1.2" => ("--tlsv1.2", "1.2"),
            "tls1.3" => ("--tlsv1.3", "1.3"),
            _ => ("", ""),
        };
        if !flag.is_empty() {
            parts.push(flag.to_string());
            parts.push(format!("{} {}", "--tls-max", max));
        }
    }
    if let Some(t) = cli.timeout {
        parts.push(format!("{} {}", lf(long, "--max-time", "--max-time"), crate::utils::format_curl_time(t)));
    }
    if let Some(v) = &cli.http_version {
        let f = match v.as_str() {
            "1.0" => "--http1.0",
            "1.1" => "--http1.1",
            "2" => "--http2",
            "2-prior-knowledge" => "--http2-prior-knowledge",
            "3-prior-knowledge" => "--http3-only",
            _ => "",
        };
        parts.push(f.to_string());
    }

    // URL
    parts.push(quote(req.url.as_str()));

    if cli.ipv4 && !cli.ipv6 {
        parts.push("-4".to_string());
    } else if cli.ipv6 && !cli.ipv4 {
        parts.push("-6".to_string());
    }
    for i in &cli.interface {
        parts.push(format!("{} {}", lf(long, "--interface", "--interface"), i));
    }
    if let Some(s) = &cli.unix_socket {
        parts.push(format!("{} {}", lf(long, "--unix-socket", "--unix-socket"), s));
    }
    for r in &cli.resolve {
        let (host, addr) = r.split_once(':').unwrap_or((r, ""));
        let port = req.url.port_or_known_default().map(|p| p.to_string()).unwrap_or_default();
        parts.push(format!("{} {}:{}:{}", lf(long, "--resolve", "--resolve"), host, port, addr));
    }

    // Method
    let explicit = cli.method.is_some();
    let has_data = req.body.to_bytes().is_some();
    if explicit {
        let m = &req.method;
        if m == "HEAD" {
            parts.push("-I".to_string());
        } else if m == "GET" && !has_data && !matches!(req.body, Body::Form(_)) {
            parts.push(format!("{} GET", lf(long, "--request", "-X")));
        } else {
            parts.push(format!("{} {}", lf(long, "--request", "-X"), m));
        }
    }

    // User headers
    for (name, value) in req.headers.iter() {
        if auto_header(name) {
            continue;
        }
        parts.push(format!("{} '{}: {}'", lf(long, "--header", "-H"), name, value));
    }

    // Auth
    if let Some(value) = crate::request::auth_header_value(cli) {
        if let Some(tok) = value.strip_prefix("Bearer ") {
            parts.push(format!("{} {}", lf(long, "--oauth2-bearer", "--oauth2-bearer"), tok));
        } else if let Some(b64) = value.strip_prefix("Basic ") {
            let creds = crate::utils::b64_decode(b64);
            let digest = cli.auth_type.as_deref() == Some("digest");
            if digest {
                parts.push("--digest".to_string());
            } else {
                parts.push(lf(long, "--basic", "--basic").to_string());
            }
            parts.push(format!("{} {}", lf(long, "--user", "-u"), quote(&creds)));
        }
    }

    // Body
    match &req.body {
        Body::Form(pairs) => {
            for (k, v) in pairs {
                parts.push(format!(
                    "{} {}",
                    lf(long, "--data-urlencode", "--data-urlencode"),
                    quote(&format!("{}={}", k, v))
                ));
            }
        }
        Body::Multipart(parts2, _) => {
            for part in parts2 {
                let mut spec = format!("{}=", part.name);
                if let Some(f) = &part.filename {
                    spec.push_str(&format!("@{}", f));
                    if let Some(m) = &part.mime {
                        spec.push_str(&format!(";type={}", m));
                    }
                } else {
                    spec.push_str(&String::from_utf8_lossy(&part.content));
                    if let Some(m) = &part.mime {
                        spec.push_str(&format!(";type={}", m));
                    }
                }
                parts.push(format!("-F {}", quote(&spec)));
            }
        }
        Body::File(_, _, _) => {
            parts.push(format!("{} '{}: {}'", lf(long, "--header", "-H"), "content-type", req.body.content_type().unwrap_or_default()));
            parts.push(format!("{} @{}", lf(long, "--data-binary", "--data-binary"), req.file_body_path.clone().unwrap_or_default()));
        }
        Body::Json(_) | Body::JsonRaw(_) | Body::None => {
            if let Some(ct) = req.body.content_type() {
                parts.push(format!("{} '{}: {}'", lf(long, "--header", "-H"), "content-type", ct));
            }
            parts.push(format!("{} '{}: {}'", lf(long, "--header", "-H"), "accept", req.accept.clone()));
            if let Some(bytes) = req.body.to_bytes() {
                let text = String::from_utf8_lossy(&bytes).to_string();
                parts.push(format!("{} {}", lf(long, "--data", "-d"), quote(&text)));
            }
