        parts.push(format!("{} {}", lf(long, "--cert", "-E"), c));
    }
    if let Some(c) = &cli.cert_key {
        parts.push(format!("{} {}", lf(long, "--key", "--key"), c));
    }
    if let Some(v) = &cli.ssl {
        let (flag, max) = match v.as_str() {
            "tls1" => ("--tlsv1.0", "1.0"),
            "tls1.1" => ("--tlsv1.1", "1.1"),
            "tls1.2" => ("--tlsv1.2", "1.2"),
            "tls1.3" => ("--tlsv1.3", "1.3"),
            _ => ("", ""),
        };
        if !flag.is_empty() {
            parts.push(flag.to_string());
            parts.push(format!("{} {}", "--tls-max", max));
        }
    }
    if let Some(t) = cli.timeout {
        parts.push(format!("{} {}", lf(long, "--max-time", "--max-time"), crate::utils::format_curl_time(t)));
    }
    if let Some(v) = &cli.http_version {
        let f = match v.as_str() {
            "1.0" => "--http1.0",
            "1.1" => "--http1.1",
            "2" => "--http2",
            "2-prior-knowledge" => "--http2-prior-knowledge",
            "3-prior-knowledge" => "--http3-only",
            _ => "",
        };
        parts.push(f.to_string());
    }

    // URL
    parts.push(quote(req.url.as_str()));

    if cli.ipv4 && !cli.ipv6 {
        parts.push("-4".to_string());
    } else if cli.ipv6 && !cli.ipv4 {
        parts.push("-6".to_string());
    }
    for i in &cli.interface {
        parts.push(format!("{} {}", lf(long, "--interface", "--interface"), i));
    }
    if let Some(s) = &cli.unix_socket {
        parts.push(format!("{} {}", lf(long, "--unix-socket", "--unix-socket"), s));
    }
    for r in &cli.resolve {
        let (host, addr) = r.split_once(':').unwrap_or((r, ""));
        let port = req.url.port_or_known_default().map(|p| p.to_string()).unwrap_or_default();
        parts.push(format!("{} {}:{}:{}", lf(long, "--resolve", "--resolve"), host, port, addr));
    }

    // Method
    let explicit = cli.method.is_some();
    let has_data = req.body.to_bytes().is_some();
    if explicit {
        let m = &req.method;
        if m == "HEAD" {
            parts.push("-I".to_string());
        } else if m == "GET" && !has_data && !matches!(req.body, Body::Form(_)) {
            parts.push(format!("{} GET", lf(long, "--request", "-X")));
        } else {
            parts.push(format!("{} {}", lf(long, "--request", "-X"), m));
        }
    }

    // User headers
    for (name, value) in req.headers.iter() {
        if auto_header(name) {
            continue;
        }
        parts.push(format!("{} '{}: {}'", lf(long, "--header", "-H"), name, value));
    }

    // Auth
    if let Some(value) = crate::request::auth_header_value(cli) {
        if let Some(tok) = value.strip_prefix("Bearer ") {
            parts.push(format!("{} {}", lf(long, "--oauth2-bearer", "--oauth2-bearer"), tok));
        } else if let Some(b64) = value.strip_prefix("Basic ") {
            let creds = crate::utils::b64_decode(b64);
            let digest = cli.auth_type.as_deref() == Some("digest");
            if digest {
                parts.push("--digest".to_string());
            } else {
                parts.push(lf(long, "--basic", "--basic").to_string());
            }
            parts.push(format!("{} {}", lf(long, "--user", "-u"), quote(&creds)));
        }
    }

    // Body
    match &req.body {
        Body::Form(pairs) => {
            for (k, v) in pairs {
                parts.push(format!(
                    "{} {}",
                    lf(long, "--data-urlencode", "--data-urlencode"),
                    quote(&format!("{}={}", k, v))
                ));
            }
        }
        Body::Multipart(parts2, _) => {
            for part in parts2 {
                let mut spec = format!("{}=", part.name);
                if let Some(f) = &part.filename {
                    spec.push_str(&format!("@{}", f));
                    if let Some(m) = &part.mime {
                        spec.push_str(&format!(";type={}", m));
                    }
                } else {
                    spec.push_str(&String::from_utf8_lossy(&part.content));
                    if let Some(m) = &part.mime {
                        spec.push_str(&format!(";type={}", m));
                    }
                }
                parts.push(format!("-F {}", quote(&spec)));
            }
        }
        Body::File(_, _, _) => {
            parts.push(format!("{} '{}: {}'", lf(long, "--header", "-H"), "content-type", req.body.content_type().unwrap_or_default()));
            parts.push(format!("{} @{}", lf(long, "--data-binary", "--data-binary"), req.file_body_path.clone().unwrap_or_default()));
        }
        Body::Json(_) | Body::JsonRaw(_) | Body::None => {
            if let Some(ct) = req.body.content_type() {
                parts.push(format!("{} '{}: {}'", lf(long, "--header", "-H"), "content-type", ct));
            }
            parts.push(format!("{} '{}: {}'", lf(long, "--header", "-H"), "accept", req.accept.clone()));
            if let Some(bytes) = req.body.to_bytes() {
                let text = String::from_utf8_lossy(&bytes).to_string();
                parts.push(format!("{} {}", lf(long, "--data", "-d"), quote(&text)));
            }
        }
    }

    let mut out = String::new();
    if !env_prefix.is_empty() {
        out.push_str(&env_prefix);
    }
    out.push_str("curl ");
    out.push_str(&parts.join(" "));
    out
}

fn auto_header(name: &str) -> bool {
    matches!(name, "accept-encoding" | "user-agent" | "connection" | "content-length" | "host")
}

fn normalize_proxy_url(u: &str) -> String {
    match url::Url::parse(u) {
        Ok(mut url) => {
            url.set_fragment(None);
            url.to_string()
        }
        Err(_) => u.to_string(),
    }
}
