/// Print the request without sending it.
pub fn print_offline(cli: &crate::cli::Cli, req: &Request) {
    let print = crate::print::print_string(cli, true);
    let pretty = crate::print::pretty_options(cli);
    let mut pr = crate::print::Printer::new(pretty, false);
    if print.contains('H') {
        pr.print_request_headers(&req.method, &req.url, &req.headers);
    }
    if print.contains('B') {
        pr.print_request_body(&req.body);
    }
    pr.done();
}

/// Print the request as part of a real exchange.
pub fn print_request(cli: &crate::cli::Cli, req: &Request, to_stderr: bool) {
    let print = crate::print::print_string(cli, false);
    if !(print.contains('H') || print.contains('B')) {
        return;
    }
    let pretty = crate::print::pretty_options(cli);
    let mut pr = crate::print::Printer::new(pretty, to_stderr);
    if print.contains('H') {
        pr.print_request_headers(&req.method, &req.url, &req.headers);
    }
    if print.contains('B') {
        pr.print_request_body(&req.body);
    }
    pr.done();
}

/// Send the request and print the response.
pub fn send(cli: &crate::cli::Cli, _bin_name: &str, req: &Request) {
    if let Some(cert) = &cli.cert {
        load_cert(cert);
    }
    let client = client_for(cli);
    match crate::client::request(&client, &req.method, &req.url, &req.headers, req.body.to_bytes().as_deref(), true) {
        Ok(resp) => {
            crate::request::print_request(cli, req, cli.download);
            crate::print::print_response(cli, &resp, &req.url);
            let code = check_status(cli, &resp);
            std::process::exit(code);
        }
        Err(e) => {
            crate::print::print_request(cli, req, cli.download);
            let mut msg = format!("error sending request for url ({})", req.url.as_str());
            let _ = e;
            eprintln!("{}: error: {}\n\nCaused by:\n    0: client error (Connect)\n    1: tcp connect error\n    2: Connection refused (os error 111)", crate::PROGRAM, msg);
            std::process::exit(1);
        }
    }
}

fn check_status(cli: &crate::cli::Cli, resp: &crate::client::Response) -> i32 {
    if !cli.check_status || cli.quiet > 0 {
        return 0;
    }
    if resp.status >= 400 && resp.status < 500 {
        4
    } else if resp.status >= 500 {
        5
    } else {
        0
    }
}

fn load_cert(path: &str) {
    if std::fs::read(path).is_err() {
        eprintln!("{}: error: Failed to open the cert file: {}", crate::PROGRAM, path);
        std::process::exit(1);
    }
}

fn client_for(cli: &crate::cli::Cli) -> crate::client::Client {
    crate::client::Client {
