            .iter()
            .filter_map(|r| {
                let (h, a) = r.split_once(':')?;
                Some((h.to_string(), a.parse::<std::net::IpAddr>().ok()?))
            })
            .collect(),
        interface: cli.interface.clone(),
        ipv4: cli.ipv4,
        ipv6: cli.ipv6,
        unix_socket: cli.unix_socket.clone(),
        proxy: crate::client::parse_proxies(&cli.proxy),
        verify: cli.verify.clone(),
        follow: cli.follow,
        max_redirects: cli.max_redirects,
        stream: cli.stream,
    }
}
