pub struct Printer {
    pub pretty: PrettyOptions,
    pub to_stderr: bool,
    pub out: Box<dyn Write>,
}

impl Printer {
    pub fn new(pretty: PrettyOptions, to_stderr: bool) -> Printer {
        let out: Box<dyn Write> = if to_stderr {
            Box::new(std::io::stderr())
        } else {
            Box::new(std::io::stdout())
        };
        Printer { pretty, to_stderr, out }
    }
    fn write(&mut self, s: &str) {
        let _ = self.out.write_all(s.as_bytes());
    }
    pub fn done(&mut self) {
        let _ = self.out.flush();
    }
}

/// Print a response.
pub fn print_response(cli: &crate::cli::Cli, resp: &crate::client::Response, url: &url::Url) {
    let print = print_string(cli, false);
    let pretty = pretty_options(cli);
    let mut pr = Printer::new(pretty, cli.download);
    let mime = resp.content_type();
    let body_printed = print.contains('b');
    if print.contains('h') {
        pr.print_response_headers(&resp.version, resp.status, &resp.reason, &resp.headers);
    }
    if body_printed {
        pr.print_response_body(&resp.body, mime, print.contains('m'));
    }
    if print.contains('m') && !body_printed {
        pr.print_response_meta(resp.elapsed, &resp.remote_addr);
    }
    pr.done();
    let _ = url;
}
