s=s.replace("""/// Print a response.
pub fn print_response(""","""pub struct Printer {
    pub pretty: PrettyOptions,
    pub to_stderr: bool,
    pub out: Box<dyn Write>,
}

impl Printer {
    pub fn new(pretty: PrettyOptions, to_stderr: bool) -> Printer {
        let out: Box<dyn Write> = if to_stderr {
            Box::new(std::io::stderr())
        } else {
            Box::new(std::io::stdout())
        };
        Printer { pretty, to_stderr, out }
    }
    fn write(&mut self, s: &str) {
        let _ = self.out.write_all(s.as_bytes());
    }
    pub fn done(&mut self) {
        let _ = self.out.flush();
    }

    pub fn print_request_headers(&mut self, method: &str, url: &url::Url, headers: &crate::headers::Headers) {
        let path = match url.query() {
            Some(q) => format!("{}?{}", url.path(), q),
            None => url.path().to_string(),
        };
        self.write(&format!("{} {} HTTP/1.1\\n", method, path));
        let mut headers = headers.clone();
        if self.pretty.sort_headers {
            headers.sort();
        }
        for (name, value) in headers.iter() {
            self.write(&format!("{}: {}\\n", crate::utils::title_case(name), value));
        }
        self.write("\\n");
    }

    pub fn print_request_body(&mut self, body: &crate::body::Body) {
        let bytes = match body.to_bytes() {
            Some(b) => b,
            None => return,
        };
        let text = if bytes.contains(&0) {
            binary_note()
        } else if body.is_json_body() {
            if let crate::body::Body::Json(v) = body {
                if self.pretty.json_format {
                    highlight_body(&(crate::json::to_pretty_string(v, self.pretty.json_indent) + "\\n\\n"), "application/json", &self.pretty)
                } else {
                    let text = crate::json::to_compact_string(v);
                    highlight_body(&text, "application/json", &self.pretty)
                }
            } else {
                highlight_body(&String::from_utf8_lossy(&bytes), "application/json", &self.pretty)
            }
        } else if self.pretty.theme.is_some() {
            if let Some(m) = body.mime() {
                highlight_body(&String::from_utf8_lossy(&bytes), m, &self.pretty)
            } else {
                String::from_utf8_lossy(&bytes).to_string()
            }
        } else {
            String::from_utf8_lossy(&bytes).to_string()
        };
        self.write(&text);
        self.write("\\n\\n");
    }

    pub fn print_response_headers(&mut self, version: &str, status: u16, reason: &str, headers: &crate::headers::Headers) {
        self.write(&format!("{} {} {}\\n", version, status, reason));
        let mut headers = headers.clone();
        if self.pretty.sort_headers {
