            }
        } else if self.pretty.theme.is_some() {
            if let Some(m) = body.mime() {
                highlight_body(&String::from_utf8_lossy(&bytes), m, &self.pretty)
            } else {
                String::from_utf8_lossy(&bytes).to_string()
            }
        } else {
            String::from_utf8_lossy(&bytes).to_string()
        };
        self.write(&text);
        self.write("\\n\\n");
    }

