/// HTTP syntax highlighting for request and response headers.
pub mod http_syntax {
    use crate::highlight::{style_for, Theme, Style};

    fn push(out: &mut Vec<(Style, String)>, theme: &Theme, scope: &str, text: &str) {
        let style = style_for(theme, scope);
        if let Some(last) = out.last_mut() {
            if last.0 == style {
                last.1.push_str(text);
                return;
            }
        }
        out.push((style, text.to_string()));
    }

    pub fn request_line(method: &str, path: &str, version: &str, theme: &Theme) -> Vec<(Style, String)> {
        let mut out = vec![];
        push(&mut out, theme, "keyword.control.http", method);
        push(&mut out, theme, "", " ");
        push(&mut out, theme, "const.language.http", path);
        push(&mut out, theme, "", " ");
        push(&mut out, theme, "keyword.other.http", "HTTP");
        push(&mut out, theme, "punctuation.separator.http", "/");
        push(&mut out, theme, "constant.numeric.http", version);
        out
    }

    pub fn response_line(version: &str, status: &str, reason: &str, theme: &Theme) -> Vec<(Style, String)> {
        let mut out = vec![];
        push(&mut out, theme, "keyword.other.http", "HTTP");
        push(&mut out, theme, "punctuation.separator.http", "/");
        push(&mut out, theme, "constant.numeric.http", version);
        push(&mut out, theme, "", " ");
        push(&mut out, theme, "constant.numeric.http", status);
        push(&mut out, theme, "", " ");
        push(&mut out, theme, "keyword.reason.http", reason);
        out
    }

    pub fn header(name: &str, value: &str, theme: &Theme) -> Vec<(Style, String)> {
        let mut out = vec![];
        push(&mut out, theme, "support.variable.http", name);
        push(&mut out, theme, "punctuation.separator.http", ":");
        push(&mut out, theme, "", " ");
        push(&mut out, theme, "string.other.http", value);
        out
    }
}

fn write_tokens(pr: &mut Printer, tokens: &[(crate::highlight::Style, String)]) {
    for (style, text) in tokens {
        pr.write(&style.to_ansi());
        pr.write(text);
    }
}
