    let chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    let mut out: Vec<(Style, String)> = vec![];
    let mut i = 0usize;
    if *in_block_comment {
        let mut j = 0usize;
        while j + 1 < n && !(chars[j] == '*' && chars[j + 1] == '/') {
            j += 1;
        }
        if j + 1 < n {
            push(&mut out, style_for(theme, "comment.block.jsonkv"), &chars[0..j + 2]);
            *in_block_comment = false;
            i = j + 2;
        } else {
            push(&mut out, style_for(theme, "comment.block.jsonkv"), &chars[0..n]);
            return out;
        }
    }
    while i < n {
        // Try the syntax rules at this position
        if let Some((style, len)) = json_match(&chars, i) {
            push(&mut out, style_for(theme, style), &chars[i..i + len]);
            i += len;
            continue;
        }
        // Consume the run of unmatched characters as one region
        let start = i;
        while i < n && json_match(&chars, i).is_none() {
            i += 1;
        }
        push(&mut out, style_for(theme, ""), &chars[start..i]);
    }
    out
}

/// Try to match a syntax rule at `i`; returns (scope, length).
fn json_match(chars: &[char], i: usize) -> Option<(&'static str, usize)> {
    let n = chars.len();
    if i >= n {
        return None;
    }
    let c = chars[i];
    if c == '/' && chars.get(i + 1) == Some(&'/') {
        return Some(("comment.single.line.jsonkv", n - i));
    }
    if c == '/' && chars.get(i + 1) == Some(&'*') {
        let mut j = i + 2;
        while j + 1 < n && !(chars[j] == '*' && chars[j + 1] == '/') {
            j += 1;
        }
        if j + 1 < n {
            return Some(("comment.block.jsonkv", j + 2 - i));
        }
        return Some(("comment.block.jsonkv", n - i));
    }
    if c == '"' {
        // Key name: "..." followed by optional whitespace and ':'
        let mut j = i + 1;
        while j < n && chars[j] != '"' && chars[j] != '\\\\' {
            j += 1;
        }
        if j < n && chars[j] == '"' {
            let mut k = j + 1;
            while k < n && chars[k].is_whitespace() {
                k += 1;
            }
            if k < n && chars[k] == ':' {
                // The captures are separate regions
                return Some(("keyword.other.name.jsonkv.captures", j + 1 - i));
            }
        }
        // String value: consume until the closing quote, handling escapes
        let mut j = i + 1;
        while j < n {
            if chars[j] == '\\\\' && j + 1 < n && "tnr\\".contains(chars[j + 1]) {
                return Some(("string.quoted.jsonkv.escapes", j - i));
            }
            if chars[j] == '"' {
                return Some(("string.quoted.jsonkv", j + 1 - i));
            }
            j += 1;
        }
        return Some(("string.quoted.jsonkv", n - i));
    }
    if c.is_ascii_digit() {
        let mut j = i;
        let mut saw_dot = false;
        while j < n {
            if chars[j].is_ascii_digit() {
                j += 1;
            } else if chars[j] == '.' && !saw_dot {
                saw_dot = true;
                j += 1;
            } else {
                break;
            }
        }
        let end = if saw_dot && (j >= n || !chars[j - 1].is_ascii_digit()) { j - 1 } else { j };
        return Some(("constant.numeric.jsonkv", end - i));
    }
    if match_word(chars, i, "true") {
        return Some(("constant.language.boolean.jsonkv", 4));
    }
    if match_word(chars, i, "false") {
        return Some(("constant.language.boolean.jsonkv", 5));
    }
    if match_word(chars, i, "null") {
        return Some(("constant.language.null.jsonkv", 4));
    }
    None
}

