    if cli.curl {
        crate::to_curl::print_warnings(cli);
        println!("{}", crate::to_curl::to_curl(cli, req));
        return;
    }
    if cli.offline {
        print_offline(cli, req);
        return;
    }
    if let Some(cert) = &cli.cert {
        load_cert(cli, cert);
    }
    if cli.native_tls {
        eprintln!("{}: error: This binary was built without native-tls support", crate::PROGRAM);
        std::process::exit(1);
    }
    let client = client_for(cli);
    let mut current = req.url.clone();
    let mut redirects = 0usize;
    let max_redirs = cli.max_redirects.unwrap_or(usize::MAX);
    let mut last_resp: Option<crate::client::Response> = None;
    let mut history: Vec<(crate::client::Response, Request)> = vec![];
    let mut method = req.method.clone();
    let mut headers = req.headers.clone();
    let body_bytes = req.body.to_bytes();
    loop {
        match crate::client::request(&client, &method, &current, &headers, body_bytes.as_deref()) {
            Ok(resp) => {
                // Redirect handling
                let is_redirect = (300..400).contains(&resp.status);
                if is_redirect && cli.follow && redirects < max_redirs {
                    if let Some(loc) = resp.headers.get("location") {
                        let next = match url::Url::parse(loc) {
                            Ok(u) => u,
                            Err(_) => current.clone(),
                        };
                        let next = if next.host_str().is_none() {
                            current.join(loc).unwrap_or(current.clone())
                        } else {
                            next
                        };
                        history.push((resp, req.clone()));
                        current = next;
                        redirects += 1;
                        if resp.status == 303 || resp.status == 301 || resp.status == 302 {
                            if method != "HEAD" {
                                method = "GET".to_string();
                            }
                            headers = req.headers.clone();
                        }
                        continue;
                    }
                }
                last_resp = Some(resp);
                break;
            }
            Err(e) => {
                crate::print::print_request(cli, req, cli.download);
                let msg = format!("error sending request for url ({})", current.as_str());
                let _ = e;
                eprintln!(
                    "{}: error: {}\n\nCaused by:\n    0: client error (Connect)\n    1: tcp connect error\n    2: Connection refused (os error 111)",
                    crate::PROGRAM, msg
                );
                std::process::exit(1);
            }
        }
    }
    let resp = match last_resp {
        Some(r) => r,
        None => return,
    };
    crate::print::print_request(cli, req, cli.download);
    for (r, _) in &history {
        let hp = cli.history_print.clone().or_else(|| {
            if cli.all || cli.verbose > 0 {
                Some("Hb".to_string())
            } else {
                None
            }
        });
        if let Some(p) = hp {
            let mut pr = crate::print::Printer::new(crate::print::pretty_options(cli), cli.download);
            if p.contains('h') {
                pr.print_response_headers(&r.version, r.status, &r.reason, &r.headers);
            }
            if p.contains('b') {
                pr.print_response_body(&r.body, r.content_type(), false);
            }
            pr.done();
        }
    }
    crate::print::print_response(cli, &resp, &req.url);
    let code = check_status(cli, &resp.status);
    if code != 0 {
        std::process::exit(code);
    }
}

fn load_cert(cli: &crate::cli::Cli, path: &str) {
    match std::fs::read(path) {
        Err(_) => {
            eprintln!("{}: error: Failed to open the cert file: {}", crate::PROGRAM, path);
            std::process::exit(1);
        }
        Ok(content) => {
            let text = String::from_utf8_lossy(&content);
            let has_cert = text.contains("BEGIN CERTIFICATE");
            let has_key = text.contains("PRIVATE KEY");
            if !has_cert || (cli.cert_key.is_none() && !has_key) {
                eprintln!("{}: error: Failed to load the cert/cert key files\n\nCaused by:\n    0: builder error\n    1: unexpected error: private key or certificate not found", crate::PROGRAM);
                std::process::exit(1);
            }
        }
    }
}

fn check_status(cli: &crate::cli::Cli, status: u16) -> i32 {
    if !cli.check_status {
        return 0;
    }
    if (400..500).contains(&status) {
        4
    } else if (500..600).contains(&status) {
        5
    } else if (300..400).contains(&status) && !cli.follow {
        3
    } else {
        0
    }
}

fn client_for(cli: &crate::cli::Cli) -> crate::client::Client {
    crate::client::Client {
        timeout: cli.timeout.map(std::time::Duration::from_secs_f64),
        resolve: cli
            .resolve
            .iter()
            .filter_map(|r| {
                let (h, a) = r.split_once(':')?;
                Some((h.to_string(), a.parse::<std::net::IpAddr>().ok()?))
            })
            .collect(),
        interface: cli.interface.clone(),
        ipv4: cli.ipv4,
        ipv6: cli.ipv6,
        unix_socket: cli.unix_socket.clone(),
        proxy: crate::client::parse_proxies(&cli.proxy),
        verify: cli.verify.clone(),
        follow: cli.follow,
        max_redirects: cli.max_redirects,
        stream: cli.stream,
    }
}
