import probe, json, difflib
cases = [['-I','-v',':8899/echo'],['-I','-h',':8899/echo'],['-I','-p','hm',':8899/echo'],['-I',':8899/404'],['-I','-vv',':8899/echo'],['-I','-F',':8899/redirect'],['-I',':8899/loop','-F','--max-redirects','2'],['-I','--pretty','all','-v',':8899/json'],['-I','-vv',':8899/json'],['-I','-p','mb',':8899/echo'],['-I','--pretty','format',':8899/json']]
for t in cases:
    g = probe.run(t); m = probe.run(t, exe='/workspace/target/debug/xh')
    ok = g==m
    print('===',' '.join(t).ljust(36), 'MATCH' if ok else 'MISMATCH')
    if not ok:
        for line in difflib.unified_diff(g[0].splitlines(), m[0].splitlines(), n=0):
            if line[0] in '+-': print('   O', json.dumps(line[1:])[:200])
        for line in difflib.unified_diff(g[1].splitlines(), m[1].splitlines(), n=0):
            if line[0] in '+-': print('   E', json.dumps(line[1:])[:200])
        if g[2]!=m[2]: print('   rc', g[2], m[2])
" 2>&1 | head -60"}

